L15_1.m_Talk_THA = "ดมเสื้อผ้าฉันแบบนั้นอีกทีเธอสู่ขิตแน่"
L15_1.m_Talk_VTN = "Ngửi quần áo của ta như thế một lần nữa rồi đó sẽ là ngày tổ chức tang lễ của nhóc đấy."
L15_1.m_Talk_SCN = "如果你再敢把鼻子贴到我衣服上闻，我就弄死你。"
L15_1.m_Talk_DEU = "Wenn du jemals wieder so an meinen Klamotten schnüffelst, wird das der Tag deiner Beerdigung sein."
L15_1.m_Talk_FRA = "Retire ton nez de là tout de suite si tu ne veux pas le perdre définitivement."
