L17_1.m_Pos = "C"
L17_1.m_Talk_KOREA = "정산 완료. 필요했던 금액과 정확하게 일치하는군요. 훌륭합니다."
L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "精算完了。必要な金額と正確に一致していますね。お見事です。"
L17_1.m_Talk_ENG = "The accounts have been settled. That all adds up exactly to the amount we needed. Outstanding."
L17_1.m_Talk_TWN = "結算完畢，金額沒錯，正好是需要的金額，非常好。"
L17_1.m_Talk_THA = "เท่านี้ก็ปิดบัญชีได้ ทั้งหมดนั้นก็ทำให้เราได้เงินตามจำนวนที่ต้องการแล้ว เยี่ยมมาก"
L17_1.m_Talk_VTN = "Các tài khoản đã được giải quyết. Tất cả cộng lại chính xác với số tiền chúng ta cần. Xuất sắc."
L17_1.m_Talk_SCN = "结算完毕。与预计需要的金额完全吻合。非常完美。"
L17_1.m_Talk_DEU = "Die Rechnungen sind beglichen. Das summiert sich genau auf die Menge, die wir brauchten. Hervorragend."
L17_1.m_Talk_FRA = "Bien, j'ai fait les comptes. C'est parfait, exactement ce dont nous avions besoin."
L18_1 = {}
L18_1.m_CutScenKey_Talk = "HORIZON_ACT2_INTERLUDE1@18#Talk"
