L18_1.m_Crash = 30
L18_1.m_Talk_KOREA = "대표님, 그럼 저희 이제 사무실에서 안 쫓겨나는 거죠?"
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "それじゃあ代表、私たちここから追い出されなくていいんですよね？"
L18_1.m_Talk_ENG = "Does that mean we won't get kicked out of this building now, boss?"
L18_1.m_Talk_TWN = "BOSS，那我們不會被趕出去了吧？"
L18_1.m_Talk_THA = "หมายความว่าเราจะไม่โดนไล่ออกจากตึกแล้วใช่มั้ยคะบอส?"
L18_1.m_Talk_VTN = "Điều đó có nghĩa là chúng ta sẽ không bị đuổi khỏi tòa nhà này bây giờ, phải không bà chủ?"
L18_1.m_Talk_SCN = "BOSS，那我们不会被赶出办公室了吧？"
L18_1.m_Talk_DEU = "Bedeutet das, dass wir jetzt nicht aus diesem Gebäude geschmissen werden, Boss?"
L18_1.m_Talk_FRA = "Youpi ! Alors on va pas se faire expulser du bâtiment ! N'est-ce pas, boss ?"
