L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "はい、オーナーとの話し合いはお任せください。"
L19_1.m_Talk_ENG = "That's right. You can count on me to deal with the landlord."
L19_1.m_Talk_TWN = "沒錯，我會直接去和屋主談。"
L19_1.m_Talk_THA = "ใช่ ที่เหลือฉันจัดการกับเจ้าของที่เอง"
L19_1.m_Talk_VTN = "Đúng rồi. Đối phó với chủ nhà thì cứ để ta."
L19_1.m_Talk_SCN = "当然。剩下与业主的谈判就交给我吧。"
L19_1.m_Talk_DEU = "So ist es. Die Abwicklung mit dem Vermieter könnt ihr mir überlassen."
L19_1.m_Talk_FRA = "Exact. Je vais parler au propriétaire, vous pouvez être tranquille."
