L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "待て、ホライズン。"
L21_1.m_Talk_ENG = "Wait. Stop right there, Horizon."
L21_1.m_Talk_TWN = "等等，站住，地平線。"
L21_1.m_Talk_THA = "เดี๋ยว หยุดตรงนั้นเลยฮอไรซัน!"
L21_1.m_Talk_VTN = "Chờ đã. Dừng lại ngay đó, Horizon."
L21_1.m_Talk_SCN = "等下，站住。地平线。"
L21_1.m_Talk_DEU = "Moment. Bleib mal stehen, Horizon."
L21_1.m_Talk_FRA = "Un instant, Horizon."
