L25_1 = {}
L25_1.m_CutScenKey_Talk = "HORIZON_ACT2_INTERLUDE1@25#Talk"
L25_1.m_CutScenProcessKey = 25
L25_1.m_CutScenID = 3500201
L25_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_Face = "UNIT_IDLE"
L25_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L25_1.m_Pos = "L"
L25_1.m_Talk_KOREA = "뭡니까. 리타. 월급 가불은 사무소 재정 문제로 불가합니다."
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "何でしょう、リタ。給料の前借りは事務所の財政問題上できません。"
L25_1.m_Talk_ENG = "What is it, Rita? I cannot pay you in advance with our current budgetary constraints."
L25_1.m_Talk_TWN = "什麼事，麗塔？現在公司財務有點狀況，無法讓你預支薪水。"
L25_1.m_Talk_THA = "อะไรนอีกล่ะริตา? ด้วยข้อจำกัดทางงบประมาณตอนนี้ ฉันจ่ายเงินเธอล่วงหน้าไม่ได้หรอกนะ"
L25_1.m_Talk_VTN = "Gì vậy, Rita? Tôi không thể trả trước cho cô khi ngân sách của chúng ta còn eo hẹp."
L25_1.m_Talk_SCN = "怎么了？丽塔。事务所目前存在一些财政问题，没办法给你预支薪水。"
L25_1.m_Talk_DEU = "Was ist, Rita? Aufgrund unserer derzeitigen Finanzbeschränkungen kann ich dich nicht im Voraus bezahlen."
L25_1.m_Talk_FRA = "Qu'y a-t-il, Rita ? La situation financière actuelle de l'entreprise ne me permet pas de vous payer tout de suite."
L26_1 = {}
L26_1.m_CutScenKey_Talk = "HORIZON_ACT2_INTERLUDE1@26#Talk"
L26_1.m_CutScenProcessKey = 26
L26_1.m_CutScenID = 3500201
L26_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "RITA_HORIZON_NULL_NULL"
L26_1.m_Pos = "R"
L26_1.m_Talk_KOREA = "너 그게 무슨 꼬락서니야? 설마 내 옷이야?"
L26_1.m_fTalkTime = 0.03
L26_1.m_Talk_JPN = "お前はなんて格好をしてるんだ？　もしかして私の服か？"
L26_1.m_Talk_ENG = "What the hell are you wearing? Are those my clothes?"
L26_1.m_Talk_TWN = "你那身裝扮是？該不會是我的衣服吧？"
L26_1.m_Talk_THA = "เธอใส่อะไรอยู่น่ะ? นั่นมันเสื้อผ้าฉันไม่ใช่เหรอ?"
L26_1.m_Talk_VTN = "Cô đang mặc cái quái gì vậy? Đó có phải là quần áo của tôi không?"
L26_1.m_Talk_SCN = "你看看你现在的样子，不会是偷穿了我的衣服吧？"
L26_1.m_Talk_DEU = "Was zum Teufel trägst du da? Sind das etwa meine Klamotten?"
L26_1.m_Talk_FRA = "Qu'est-ce que tu portes, là ? Ne me dis pas que ce sont mes vêtements ?"
L27_1 = {}
L27_1.m_CutScenKey_Talk = "HORIZON_ACT2_INTERLUDE1@27#Talk"
L27_1.m_CutScenProcessKey = 27
L27_1.m_CutScenID = 3500201
L27_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L27_1.m_Pos = "L"
L27_1.m_Talk_KOREA = "제 프레임에는 헐렁하더군요. 다음부터는 두 치수 작게 구비해 두십시오."
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "私のフレームにはダボダボでした。次からは2サイズ小さいものを用意しておいてください。"
L27_1.m_Talk_ENG = "It was rather loose on my frame. Please prepare them two sizes smaller next time."
L27_1.m_Talk_TWN = "對我的軀殼來說有點太大，下次請準備再小2個尺寸。"
L27_1.m_Talk_THA = "มันออกจะหลวมไปสำหรับเฟรมฉันนะ คราวหน้าช่วยเตรียมไว้ให้เล็กกว่านี้สองไซค์ด้วย"
L27_1.m_Talk_VTN = "Nó khá lỏng lẻo trên bộ khung của tôi. Vui lòng chuẩn bị bộ nhỏ hơn hai cỡ vào lần sau nhé."
L27_1.m_Talk_SCN = "对我的躯壳来说有些太宽松了。下次请准备小两号的衣服。"
L27_1.m_Talk_DEU = "An mir sitzen sie ziemlich locker. Bitte kauf sie beim nächsten Mal zwei Nummern kleiner."
L27_1.m_Talk_FRA = "Oh, ça ? Ils étaient un peu trop amples pour mon armature. La prochaine fois, prévoyez deux tailles en dessous si vous voulez bien."
L28_1 = {}
L28_1.m_CutScenKey_Talk = "HORIZON_ACT2_INTERLUDE1@28#Talk"
L29_1 = 28
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 3500201
L28_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_Face = "UNIT_IDLE"
L28_1.m_CharStrID = "RITA_HORIZON_NULL_NULL"
L28_1.m_Pos = "R"
L29_1 = "남의 옷을 멋대로 꺼내 입어 놓고 잘도 지껄이는군."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "人の服を勝手に着ておいてよく言う。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Look at you run your mouth after wearing my clothes without permission."
L28_1.m_Talk_ENG = L29_1
L29_1 = "隨便拿人家的衣服出來穿，還要求那麼多。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "เอาเสื้อผ้าฉันไปใส่โดยไม่ได้รับอนุญาตแล้วยังจะมาปากแก๋วอีก"
L28_1.m_Talk_THA = L29_1
L29_1 = "Xem cô chống chế sau khi mặc trộm quần áo của tôi kìa."
L28_1.m_Talk_VTN = L29_1
L29_1 = "你偷穿别人的衣服，还敢大放厥词。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Wie dreist du bist, obwohl du meine Klamotten ohne Erlaubnis getragen hast."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Et puis quoi, encore ? Je me souviens pas t'avoir donné ma permission !"
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "HORIZON_ACT2_INTERLUDE1@29#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 29
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 3500201
L29_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_Face = "UNIT_LAUGH"
L29_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L29_1.m_Pos = "L"
L30_1 = "합리적인 이유가 있기 때문이죠."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "合理的な理由があるからです。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "There's a method to this madness."
L29_1.m_Talk_ENG = L30_1
L30_1 = "我當然是有合理的理由。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "มันมีที่มาที่ไปอยู่นะ"
L29_1.m_Talk_THA = L30_1
L30_1 = "Có một cách để xử lý sự điên rồ này."
L29_1.m_Talk_VTN = L30_1
L30_1 = "我有合理的理由。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Das liegt daran, dass ich einen guten Grund dafür habe."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Tout cela est parfaitement logique, pourtant."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "HORIZON_ACT2_INTERLUDE1@30#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L30_1.m_CutScenProcessKey = 30
L30_1.m_CutScenID = 3500201
L30_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L30_1.m_bWaitClick = true
