L30_1.m_Face = "UNIT_IDLE"
L30_1.m_CharStrID = "RITA_HORIZON_NULL_NULL"
L30_1.m_Pos = "R"
L31_1 = "어디 지껄여 봐."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "はあ……言ってみろ。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Oh, great. I'd really love to know."
L30_1.m_Talk_ENG = L31_1
L31_1 = "說來聽聽。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "อ้อ เยี่ยมเลย อยากรู้ใจจะขาดละ"
L30_1.m_Talk_THA = L31_1
L31_1 = "Tuyệt. Tôi thực sự muốn biết đấy."
L30_1.m_Talk_VTN = L31_1
L31_1 = "那你说说看。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Ich höre?"
L30_1.m_Talk_DEU = L31_1
L31_1 = "J'ai hâte d'entendre ton explication."
L30_1.m_Talk_FRA = L31_1
