L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 32
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 3500201
L32_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_Face = "UNIT_IDLE"
L32_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L32_1.m_Pos = "C"
L33_1 = "휴먼들의 기록 영상을 분석한 결과, 리타와 저의 차이점을 파악하는 데 성공했습니다."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "ヒューマンたちの記録映像を分析した結果、リタと私の違いを把握することに成功しました。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Upon analyzing human video records, I've finally identified the key difference between you and me."
L32_1.m_Talk_ENG = L33_1
L33_1 = "分析人類紀錄片的結果，成功發現麗塔和我的差異，"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ตอนที่ฉันกำลังวิเคราะห์บันทึกวิดีโอของมนุษย์อยู่ ก็สามารถระบุความแตกต่างประการสำคัญระหว่างเธอกับฉันได้ในที่สุด"
L32_1.m_Talk_THA = L33_1
L33_1 = "Sau khi phân tích các bản ghi video của con người, cuối cùng tôi đã xác định được sự khác biệt chính giữa các cô và tôi."
L32_1.m_Talk_VTN = L33_1
L33_1 = "根据我对人类记录视频的分析结果，甄别出了我和丽塔之间的差异。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Als Resultat der Analyse menschlicher Videoaufzeichnungen habe ich endlich den Unterschied zwischen uns verstanden."
L32_1.m_Talk_DEU = L33_1
L33_1 = "En visionnant des archives sur les êtres humains, j'ai fini par comprendre ce qui nous différenciait, vous et moi."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "HORIZON_ACT2_INTERLUDE1@33#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 33
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 3500201
L33_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L33_1.m_Pos = "C"
L34_1 = "바로 상대를 위협하는 천박한 복장이죠."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "それは相手を威嚇する下品な服装でした。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "It's none other than this threateningly vulgar attire."
L33_1.m_Talk_ENG = L34_1
L34_1 = "就是威脅對方的低俗服裝。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ซึ่งก็คือเสื้อผ้าชั้นต่ำทำร้ายตานี่ล้วนๆ"
L33_1.m_Talk_THA = L34_1
L34_1 = "Không có gì khác chính là bộ trang phục thô tục đầy đe dọa này."
L33_1.m_Talk_VTN = L34_1
L34_1 = "结论是——穿没品位的服装能够让对方感到威胁。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Er liegt in dieser bedrohlich-vulgären Kleidung."
L33_1.m_Talk_DEU = L34_1
L34_1 = "La réponse, vous l'avez devant vous. C'est cet attirail vulgaire et menaçant."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "HORIZON_ACT2_INTERLUDE1@34#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 34
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 3500201
L34_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_Face = "UNIT_PRIDE"
L34_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L34_1.m_Pos = "C"
L35_1 = "참고로 이 재킷은 채무자에게 이자 대신 받았습니다."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "ちなみにこのジャケットは債務者から利子の代わりにもらったものです。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "For the record, I procured this jacket from a debtor in lieu of an interest payment."
L34_1.m_Talk_ENG = L35_1
L35_1 = "提醒你，這件外套債務人的利息抵押品。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "บอกไว้เอาลงหน่วยความจำนะคะ แจ็คเก็ตนี่ฉันเอามาจากลูกหนี้แทนดอกเบี้ย"
L34_1.m_Talk_THA = L35_1
L35_1 = "Với lại nói cho cô rõ, tôi đã mua chiếc áo khoác này từ một con nợ thay cho việc trả lãi."
L34_1.m_Talk_VTN = L35_1
L35_1 = "另外作为参考，这件夹克其实是从债务者那抵债拿的。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Übrigens habe ich diese Jacke von einem Schuldner anstelle einer Zinszahlung erhalten."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Oh et la veste, je l'ai prise à un client en guise de paiement pour ce qu'il me devait."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
