L35_1.m_fWaitTime = 0
L36_1 = "UNIT_DESPAIR"
L35_1.m_Face = L36_1
L35_1.m_CharStrID = "RITA_HORIZON_NULL_NULL"
L35_1.m_Pos = "C"
L36_1 = "나랑 꼬맹이가 쥐꼬리만한 이자 받아내려고 생선 더미를 파헤치는 동안 말이지."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "私とガキが小銭程度の利子をもらおうと魚の山を漁っている間にな。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Of course you did… While the kid and I were digging through fish to squeeze out a few pennies…"
L35_1.m_Talk_ENG = L36_1
L36_1 = "我和小鬼在海鮮市場收微薄的利息時，你在搞這些是吧。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "แน่ละ... ส่วนฉันกับเด็กนั่นก็คุ้ยปลาหาเศษตังค์..."
L35_1.m_Talk_THA = L36_1
L36_1 = "Tất nhiên là cô đã làm thế rồi… Trong khi tôi và đứa trẻ đang bới cá để kiếm vài xu lẻ…"
L35_1.m_Talk_VTN = L36_1
L36_1 = "你是说在我和小不点一起为了丁点利息在海鲜堆里边找人的时候吗。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Aha, war ja klar. Während die Kleine und ich zwischen den kleinen Wichten durchgewühlt haben, um ein paar Cent Zinsen aus den Leuten herauszupressen ..."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Tu t'es bien amusée à ce que je vois. Et nous pendant ce temps, on retournait tous les stands de maquereaux de la ville pour quelques piécettes..."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
