L39_1 = "HORIZON_ACT2_INTERLUDE1@38#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 38
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 3500201
L38_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_Face = "UNIT_IDLE"
L38_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L38_1.m_Pos = "L"
L39_1 = "불만 있습니까, 휴먼?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "文句がありますか、ヒューマン？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Do you mean to file a complaint, human?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "有什麼不滿嗎，人類？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "จะยื่นเรื่องร้องเรียนรึเปล่าคะ คุณมนุษย์?"
L38_1.m_Talk_THA = L39_1
L39_1 = "Cô có ý định nộp đơn khiếu nại không, con người?"
L38_1.m_Talk_VTN = L39_1
L39_1 = "你有不满吗，人类？"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Hast du ein Problem, Mensch?"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Vous avez une plainte à formuler, humaine ?"
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "HORIZON_ACT2_INTERLUDE1@39#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 39
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 3500201
L39_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_Face = "UNIT_PRIDE"
L39_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L39_1.m_Pos = "L"
L40_1 = "그렇다면 채무를 청산하고 대표가 되십시오. 도전은 언제든 환영입니다."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "ならば債務を清算して代表になってください。挑戦はいつでも歓迎します。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Then pay off your debt and take over this company. I always welcome a good challenge."
L39_1.m_Talk_ENG = L40_1
L40_1 = "那就清償債務，換你來當老闆。隨時歡迎你來挑戰。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ถ้าอย่างนั้นก็จ่ายหนี้แล้วยึดบริษัทนี่ไปเลยค่ะ ฉันยินดีรับความท้าทายดีๆ อยู่แล้ว"
L39_1.m_Talk_THA = L40_1
L40_1 = "Vậy thì trả hết nợ đi rồi tiếp quản công ty này. Tôi luôn hoan nghênh một thử thách tốt."
L39_1.m_Talk_VTN = L40_1
L40_1 = "那这样的话就请先还清债务，然后成为BOSS。我随时欢迎你的挑战。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Dann zahlen deine Schulden ab und übernimm diese Firma. Ich freue mich über jede Herausforderung."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Dans ce cas, remboursez votre dette et prenez donc ma place. J'accepte le défi à bras ouverts."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "HORIZON_ACT2_INTERLUDE1@40#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 40
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 3500201
L40_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_CharStrID = "RITA_HORIZON_NULL_NULL"
L40_1.m_Pos = "R"
L41_1 = "시끄러. 내가 아무리 썩었어도 이딴 구멍가게나 탐낼 정도는 아냐."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "うるさい。いくら私が腐った人間でも、こんなちっさい会社を乗っ取るつもりはない。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Shut up. I may be rotten to the core, but not enough to covet this hole in the wall."
L40_1.m_Talk_ENG = L41_1
L41_1 = "吵死了，我再怎麼落魄，也不會打這種小公司的歪主意。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "เงียบไปเลยปะ ฉันอาจคดยันข้องอยันกระดูก แต่ก็ไม่อยากได้ตึกรูหนูนี่หรอก"
L40_1.m_Talk_THA = L41_1
L41_1 = "Câm miệng. Tôi có thể bị thối rữa từ tận bên trong, nhưng không phải lúc nào cũng nghĩ những chuyện xấu xa."
L40_1.m_Talk_VTN = L41_1
L41_1 = "吵死了。就算我再怎么失败，也不会觊觎你这个破烂公司。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Schnauze. Ich mag bis ins Mark verdorben sein, aber nicht genug, um diesen Tante-Emma-Laden an mich reißen zu wollen."
L40_1.m_Talk_DEU = L41_1
L41_1 = "La ferme. Je suis peut-être pourrie, mais au point d'avoir des vues sur un taudis pareil."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
