L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 47
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 3500201
L47_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_BGFileName = "office_detect"
L47_1.m_Face = "UNIT_PRIDE"
L47_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L47_1.m_Pos = "L"
L48_1 = "어떻습니까. 대시."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "どうですか、ダッシュ。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "What do you think, Dash?"
L47_1.m_Talk_ENG = L48_1
L48_1 = "黛西，你覺得怎麼樣？"
L47_1.m_Talk_TWN = L48_1
L48_1 = "แดชล่ะ ว่ายังไง?"
L47_1.m_Talk_THA = L48_1
L48_1 = "Nhóc nghĩ sao, Dash?"
L47_1.m_Talk_VTN = L48_1
L48_1 = "你觉得怎么样，黛西。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Was denkst du, Dash?"
L47_1.m_Talk_DEU = L48_1
L48_1 = "Et vous, Dash ? Qu'est-ce vous en pensez ?"
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "HORIZON_ACT2_INTERLUDE1@48#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 48
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 3500201
L48_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L48_1.m_Pos = "L"
L49_1 = "이렇게 입고 다니면 어떤 휴먼이라도 제가 무시무시한 사채업자란 사실을 인지하겠죠."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "こんな格好をしていれば、どんなヒューマンでも私が恐ろしい闇金業者だという事実を認知するでしょう。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Surely any human would instantly recognize that I am a formidable loan shark if I dress like this?"
L48_1.m_Talk_ENG = L49_1
L49_1 = "穿這樣人類看到我，也會以為我是可怕的高利貸吧？"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ถ้าฉันแต่งตัวอย่างนี้ มนุษย์คนไหนเห็นก็รู้ทันทีว่านี่เจ้าหนี้เงินกู้หน้าเลือดใช่มั้ยคะ?"
L48_1.m_Talk_THA = L49_1
L49_1 = "Chắc hẳn bất kỳ con người nào cũng sẽ nhận ra ngay rằng tôi là một kẻ cho vay nặng lãi nếu tôi ăn mặc như thế này?"
L48_1.m_Talk_VTN = L49_1
L49_1 = "如果我穿成这样，不管是什么人都会一眼认出我是收账的吧。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Es würde bestimmt jeder Mensch sofort erkennen, dass ich ein imposanter Kredithai bin, wenn ich mich so anziehe, oder?"
L48_1.m_Talk_DEU = L49_1
L49_1 = "J'ai l'air d'un vrai requin, non ? Je suis sûre qu'en déambulant en ville avec ces vêtements, les humains auront peur de moi."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "HORIZON_ACT2_INTERLUDE1@49#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 49
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 3500201
L49_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L49_1.m_Face = "UNIT_LAUGH"
L49_1.m_CharStrID = "DASH_HORIZON_NULL_NULL"
L49_1.m_Pos = "R"
L49_1.m_Crash = 30
L50_1 = "헤헷. 대표님은 어떻게 입어도 귀엽기만 한데요."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "エヘッ。代表はどんな服を着ても可愛いですよ。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Hehe. You're adorable no matter what you wear, boss."
L49_1.m_Talk_ENG = L50_1
L50_1 = "嘿嘿，BOSS不管穿什麼都很可愛。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "แหะแหะ คุณจะแต่งอะไรก็น่ารักทั้งนั้นแหละค่ะบอส"
L49_1.m_Talk_THA = L50_1
L50_1 = "Hehe. Dù cô mặc gì đi chăng nữa thì cô cũng đáng yêu lắm."
L49_1.m_Talk_VTN = L50_1
L50_1 = "嘿嘿。BOSS你不管穿成什么样都很可爱。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Hehe. Du bist hinreißend, egal, was du trägst, Boss."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Un requin ? Pour moi tu es juste adorable boss, peu importe ce que tu portes !"
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "HORIZON_ACT2_INTERLUDE1@50#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L50_1.m_CutScenProcessKey = 50
L50_1.m_CutScenID = 3500201
L50_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "UNIT_DESPAIR"
L50_1.m_Face = L51_1
L50_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L50_1.m_Pos = "L"
L51_1 = "그러면 곤란합니다. 흉악범도 겁먹을 만큼 더러운 인상이 수금에 효율적이니까요."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "それでは困ります。凶悪犯も恐れるような恐ろしい印象が集金に効率的ですからね。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "That won't do at all. Maintaining an intimidating presence that instills fear even in the toughest criminals is essential for effective collection."
L50_1.m_Talk_ENG = L51_1
L51_1 = "這樣不行，必須是連彪形大漢都會怕的形象，討債才會有效率。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "แบบนั้นก็ไม่ได้การสิ การรักษาภาพลักษณ์ที่ดูคุกคามจนแม้แต่อาชญากรที่กล้าที่สุดยังกลัวหัวปักหัวปำ เป็นเรื่องจำเป็นต่อการเก็บหนี้อย่างมีประสิทธิภาพนะคะ"
L50_1.m_Talk_THA = L51_1
L51_1 = "Không được. Phải có một diện mạo đáng sợ ngay cả với những tên tội phạm cứng rắn nhất mới là điều cần thiết để thu nợ hiệu quả."
L50_1.m_Talk_VTN = L51_1
L51_1 = "那这样就难办了。因为有能吓住凶恶罪犯的恐怖形象，才能对收债效率有所帮助。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Das geht aber nicht. Eine einschüchternde Präsenz, die selbst den härtesten Kriminellen Angst einflößt, ist für eine effektive Abzahlung unerlässlich."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Vraiment ? C'est un problème. Si je veux que le recouvrement se passe bien, je dois susciter l'intimidation auprès des clients."
L50_1.m_Talk_FRA = L51_1
