L2_1 = "리타의 실적을 통해 이미 증명된 사실이죠."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "リタの実績によってすでに証明された事実です。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "A fact already proven through Rita's track record."
L1_1.m_Talk_ENG = L2_1
L2_1 = "麗塔的業績也證明這個論點沒錯。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ประวัติการทำงานของริตาพิสูจน์ความจริงข้อนี้มาแล้ว"
L1_1.m_Talk_THA = L2_1
L2_1 = "Một sự thật đã được chứng minh qua thành tích của Rita."
L1_1.m_Talk_VTN = L2_1
L2_1 = "这是通过丽塔实际业绩得到证明的事实。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Diese Tatsache wurde bereits durch Ritas Erfolgsbilanz bewiesen."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Une conjecture que les résultats de Rita ne font que confirmer."
L1_1.m_Talk_FRA = L2_1
