L2_1.m_Pos = "L"
L3_1 = "물리력을 사용할 필요 없이 채무자들에게서 이자를 받아 오니까요."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "物理的な力の行使に頼らず、債務者から毎月の返済額をしっかり受け取っていますから。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "She always collects, even without resorting to violence."
L2_1.m_Talk_ENG = L3_1
L3_1 = "不需要動手，也可以讓債務人乖乖交出利息。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "เธอเก็บหยี้ได้เสมอ ต่อให้ไม่ต้องพึ่งพาความรุนแรงก็ตาม"
L2_1.m_Talk_THA = L3_1
L3_1 = "Cô ấy luôn thu được nợ mà thậm chí không cần dùng đến bạo lực."
L2_1.m_Talk_VTN = L3_1
L3_1 = "不用使用物理手段，就能让债务者偿还利息。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Denn sie sammelt Zinsen von den Schuldnern ein, ohne physikalische Kraft aufzuwenden."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Elle obtient toujours ce qu'elle veut, sans jamais avoir recours à la violence."
L2_1.m_Talk_FRA = L3_1
