L6_1 = "HORIZON_ACT2_INTERLUDE1@55#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 55
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 3500201
L5_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_Face = "UNIT_HATE"
L5_1.m_CharStrID = "RITA_HORIZON_NULL_NULL"
L5_1.m_Pos = "C"
L6_1 = "넌 뭘 또 저 헛소리에 혹해서 남의 얼굴을 빤히 쳐다봐."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "おい。あんなでたらめに納得したのか？"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Seriously? You buy into that crap? Stop staring at me."
L5_1.m_Talk_ENG = L6_1
L6_1 = "盯著我看幹嘛？那種毫無根據的話你也信。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "เอาจริงดิ? เธอเชื่อเรื่องเลอะเทอะนี่เหรอ? หยุดจ้องฉันเลยนะ"
L5_1.m_Talk_THA = L6_1
L6_1 = "Thật ư? Cô lấy cái tin tào lao đó ở đâu vậy? Đừng có nhìn tôi nữa."
L5_1.m_Talk_VTN = L6_1
L6_1 = "你怎么也被她的奇怪理论迷惑了？还在旁边起哄？"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Ernsthaft? Du nimmst diesen Mist ernst? Hör auf, zu starren."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Arrête de me regarder comme ça ! N'écoute pas ses bêtises."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "HORIZON_ACT2_INTERLUDE1@56#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 56
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 3500201
L6_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "UNIT_DESPAIR"
L6_1.m_Face = L7_1
L6_1.m_CharStrID = "RITA_HORIZON_NULL_NULL"
L6_1.m_Pos = "C"
L7_1 = "호라이즌, 그렇게 똘마니처럼 차려 입어도 널 데리고 다닐 일은 없어."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "ホライズン、そんなチンピラみたいな格好をしたってお前を連れていくことはない。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Just so you know, Horizon, I'm not going to let you tag along just because you're dressed like a thug."
L6_1.m_Talk_ENG = L7_1
L7_1 = "地平線，就算你穿得像小嘍囉一樣，我也不會帶你去的。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "จะบอกให้เอาบุญนะฮอไรซัน ฉันไม่ยอมให้เธอมาด้วยแค่เพราะเธอแต่งตัวเหมือนกุ๊ยหรอก"
L6_1.m_Talk_THA = L7_1
L7_1 = "Nói cho cô biết nhé, Horizon, tôi sẽ không mang cô theo chỉ vì cô ăn mặc như một tên côn đồ."
L6_1.m_Talk_VTN = L7_1
L7_1 = "地平线，就算你穿得像个混混，我也不会带你去收账的。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Nur damit du es weißt, Horizon. Ich nehme dich nicht mit, nur weil du wie ein Schläger gekleidet bist."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Et ne crois pas que je vais t'emmener avec moi juste parce que tu te donnes des airs de racaille, Horizon."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "HORIZON_ACT2_INTERLUDE1@57#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 57
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 3500201
L7_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_Face = "UNIT_IDLE"
L7_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L7_1.m_Pos = "C"
L8_1 = "어째서입니까. 저는 대표로서 직원들의 근무 태도를 감독해야 할 의무가 있습니다."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "なぜですか。私は代表として、社員の勤務態度を監督する義務があります。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Why not? As your supervisor, it is my responsibility to monitor your performance."
L7_1.m_Talk_ENG = L8_1
L8_1 = "為什麼？我身為老闆，有義務要監督員工的工作狀況。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ทำไมละคะ? ในฐานะหัวหน้างานแล้วนี่ ฉันมีหน้าที่ต้องสอดส่องดูแลผลงานของคุณนะคะ"
L7_1.m_Talk_THA = L8_1
L8_1 = "Tại sao không? Là cấp trên, tôi có trách nhiệm theo dõi tình hình làm việc của cô."
L7_1.m_Talk_VTN = L8_1
L8_1 = "为什么呢。作为BOSS，我也有监督职员们工作态度的义务啊。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Warum nicht? Als die Vorsitzende muss ich die Leistung meiner Mitarbeiter überwachen."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Et pourquoi ? Je suis votre supérieure, c'est mon rôle de superviser vos opérations."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "HORIZON_ACT2_INTERLUDE1@58#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 58
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 3500201
L8_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_Face = "UNIT_IDLE"
L8_1.m_CharStrID = "RITA_HORIZON_NULL_NULL"
L8_1.m_Pos = "C"
L9_1 = "그럼 항상 하던 대로 드론으로 따라다녀."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "じゃあ、いつもどおりドローンでやればいい。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Then just keep using the drone as usual."
L8_1.m_Talk_ENG = L9_1
L9_1 = "那你像之前那樣，用無人機的方式跟著。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "งั้นก็ใช้โดรนอย่างเคยไปสิ"
L8_1.m_Talk_THA = L9_1
L9_1 = "Thế thì cứ tiếp tục sử dụng drone như bình thường đi."
L8_1.m_Talk_VTN = L9_1
L9_1 = "那你就像之前一样，使用无人机吧。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Dann folg uns per Drohne, so wie immer."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Continue d'envoyer ton drone, dans ce cas. Ça suffit très bien comme ça."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "HORIZON_ACT2_INTERLUDE1@59#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 59
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 3500201
L9_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "RITA_HORIZON_NULL_NULL"
L9_1.m_Pos = "C"
L10_1 = "애초에 이 사무실 월세 밀린 것도 네가 프론트 베이에서 사고친 탓이잖아."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "そもそも、この事務所の賃料の支払いが滞ったのもお前がフロントベイでやらかしたせいだろ。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "The whole reason we're behind on rent in the first place is because you messed up big time at Front Bay."
L9_1.m_Talk_ENG = L10_1
L10_1 = "我們付不出租金，都是因為你在前灣闖禍不是嗎？"
L9_1.m_Talk_TWN = L10_1
L10_1 = "เหตุผลเดียวที่ทำให้เราค้างค่าเช่ามาแต่แรกก็เพราะเธอไปทำฟรอนต์เบย์ไว้ซะเละตุ้มเป๊ะไง"
L9_1.m_Talk_THA = L10_1
L10_1 = "Toàn bộ lý do khiến chúng ta chậm trả tiền thuê ngay từ đầu là vì cô đã quậy tung Front Bay."
L9_1.m_Talk_VTN = L10_1
L10_1 = "最开始这个办公室会欠房租，也是因为你在前湾那边闹出事故不是吗。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Wir sind überhaupt erst mit der Miete im Rückstand, weil du in Front Bay so viel vermasselt hast."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Je dois vraiment te rappeler que c'est à cause de ton bazar à Front Bay qu'on est autant à la ramasse pour payer nos loyers ?"
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "HORIZON_ACT2_INTERLUDE1@60#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L10_1.m_CutScenProcessKey = 60
L10_1.m_CutScenID = 3500201
L10_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_CharStrID = "RITA_HORIZON_NULL_NULL"
L10_1.m_Pos = "C"
L11_1 = "저 일만 키우는 꼬맹이도 너에 비하면 베테랑이야."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "あの仕事ばかり増やすガキだって、お前に比べればベテランさ。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Even this little troublemaker is a seasoned pro compared to you."
L10_1.m_Talk_ENG = L11_1
L11_1 = "連那個整天闖禍的小鬼都比你強。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "เทียบกับเธอแล้วนะ ยัยตัวป่วนจิ๋วนี่ยังดูเป็นมืออาชีพมากประสบการณ์กว่าเลย"
L10_1.m_Talk_THA = L11_1
L11_1 = "Ngay cả kẻ gây rối nho nhỏ này cũng là một chuyên gia dày dạn so với cô."
L10_1.m_Talk_VTN = L11_1
L11_1 = "就算是天天惹事的小不点，也比你老练的多。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Selbst dieser kleine Unruhestifter dort ist im Vergleich zu dir ein waschechter Profi."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Même cette fauteuse de trouble passe pour une pro à côté de toi."
L10_1.m_Talk_FRA = L11_1
