L14_1 = "HORIZON_ACT2_INTERLUDE1@63#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 63
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 3500201
L13_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L13_1.m_bWaitClick = true
