L13_1.m_Face = "UNIT_LAUGH"
L13_1.m_CharStrID = "DASH_HORIZON_NULL_NULL"
L14_1 = "L_M_I"
L13_1.m_Pos = L14_1
L13_1.m_Crash = 30
L14_1 = "정말요?! 언니 그거 칭찬 맞죠?!"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "本当ですか！？　お姉ちゃん、それって褒め言葉ですよね？"
L13_1.m_Talk_JPN = L14_1
L14_1 = "You mean it?! That was a compliment, right?!"
L13_1.m_Talk_ENG = L14_1
L14_1 = "真的嗎？！姊姊是在稱讚我對吧？"
L13_1.m_Talk_TWN = L14_1
L14_1 = "จริงเหรอคะ?! นั่นชมกันใช่มั้ยคะ?!"
L13_1.m_Talk_THA = L14_1
L14_1 = "Cô thật sự có ý như vậy sao?! Đó là một lời khen, phải không?!"
L13_1.m_Talk_VTN = L14_1
L14_1 = "真的吗？！姐姐刚才是夸我的吧？！"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Echt?! Das war ein Kompliment, oder?!"
L13_1.m_Talk_DEU = L14_1
L14_1 = "Vraiment ?! C'est un compliment, n'est-ce pas ?"
L13_1.m_Talk_FRA = L14_1
