L15_1 = "UNIT_DESPAIR"
L14_1.m_Face = L15_1
L14_1.m_CharStrID = "RITA_HORIZON_NULL_NULL"
L14_1.m_Pos = "R"
L15_1 = "……둘 다 밥값 못한다고 정정하지."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "……二人とも飯代程度も稼げないと訂正する。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "…I take that back. Both of you are useless."
L14_1.m_Talk_ENG = L15_1
L15_1 = "……我的意思是你們2個都是賠錢貨。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "... ขอถอนคำพูดละกัน พวกเธอนี่ไม่ได้ความกันทั้งคู่เลย"
L14_1.m_Talk_THA = L15_1
L15_1 = "…Tôi rút lại câu nói đó. Cả hai người đều vô dụng."
L14_1.m_Talk_VTN = L15_1
L15_1 = "……是我错了，你们两个都是赔钱货。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Ich nehme das zurück. Ihr beide seid nutzlos."
L14_1.m_Talk_DEU = L15_1
L15_1 = "... Je retire ce que je viens de dire. Y'en a pas une pour rattraper l'autre."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "HORIZON_ACT2_INTERLUDE1@65#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 65
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 3500201
L15_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L15_1.m_bWaitClick = true
