L15_1.m_Face = "UNIT_SURPRISE"
L15_1.m_CharStrID = "DASH_HORIZON_NULL_NULL"
L15_1.m_Pos = "L"
L15_1.m_Crash = 20
L16_1 = "아앗! 줬다 뺐는 건 나쁘다고 TV에서 그랬는데!"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "ええー！　話を二転三転するのはよくないことってテレビで見ましたよ！？"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Aw! That's totally not fair!"
L15_1.m_Talk_ENG = L16_1
L16_1 = "怎麼這樣！電視上說，說過的話不能反悔，這樣是不對的喔！"
L15_1.m_Talk_TWN = L16_1
L16_1 = "เอ๊า! ไม่แฟร์เลยอะค่ะ!"
L15_1.m_Talk_THA = L16_1
L16_1 = "Aw! Điều đó hoàn toàn không công bằng!"
L15_1.m_Talk_VTN = L16_1
L16_1 = "啊啊！怎么可以这样。哪有夸完之后又取消的道理！"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Ach menno! Das ist nicht fair!"
L15_1.m_Talk_DEU = L16_1
L16_1 = "Hé, c'est pas bien de revenir sur ses paroles ! Ils ont dit ça à la télé !"
L15_1.m_Talk_FRA = L16_1
