L18_1 = "HORIZON_ACT2_INTERLUDE1@67#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 67
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 3500201
L17_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_Face = "UNIT_PRIDE"
L17_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L17_1.m_Pos = "C"
L18_1 = "종결된 사건을 다시 거론하다니 리타도 휴먼답게 쪼잔하군요."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "終結した事件を再び取り上げるなんて、リタもヒューマンらしく器が小さいですね。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "It appears even you're not exempt from human pettiness, bringing up what's already water under the bridge."
L17_1.m_Talk_ENG = L18_1
L18_1 = "已經結束的事還拿出來翻舊帳，看來麗塔果然是人類呢，很小心眼。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "กลายเป็นว่าแม้แต่เธอก็ไม่พ้นความหยุมหยิมแบบมนุษย์นะคะ ช่างฟื้นฝอยหาตะเข็บ"
L17_1.m_Talk_THA = L18_1
L18_1 = "Có vẻ như cô cũng không mất đi những tính khí nhỏ nhen của con người, cứ hay bới móc lại những chuyện cũ."
L17_1.m_Talk_VTN = L18_1
L18_1 = "竟然将已经结束的事情重新提起，果然丽塔也像普通人类那样小气。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Typisch Mensch. Wie kleinlich von dir, einen bereits abgeschlossenen Fall wieder herauszukramen."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Vous êtes bien une humaine Rita, même vous. Remettre cette affaire sur le tapis..."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "HORIZON_ACT2_INTERLUDE1@68#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 68
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 3500201
L18_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L18_1.m_Pos = "C"
L19_1 = "반면에 기계인 저는 사건 당시의 상황을 분석해 냉각기 설계를 개선하였습니다."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "その反面、機械である私は事件当時の状況を分析して、冷却器の設計を改善しました。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Whereas in contrast, being a machine I analyzed the incident to improve the design of my cooling devices."
L18_1.m_Talk_ENG = L19_1
L19_1 = "相反的，身為機器的我，則是分析事件當時的情況後，改善冷卻裝置的設計。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ในทางตรงข้ามนี่ จักรกลอย่างฉันนั้นวิเคราะห์เหตุการณ์ต่างๆ เพื่อพัฒนาการออกแบบให้เครื่องทำความเย็นของตัวเอง"
L18_1.m_Talk_THA = L19_1
L19_1 = "Trong khi ngược lại, là một cỗ máy, tôi đã phân tích sự cố để cải thiện thiết kế các thiết bị làm mát của mình."
L18_1.m_Talk_VTN = L19_1
L19_1 = "相反的是，我作为机器却通过分析此次事件重新设计和改善了冷却系统。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Im Vergleich zu dir bin ich eine Maschine und habe den damaligen Vorfall analysiert, um das Design meiner Kühlgeräte zu verbessern."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Moi, la machine, j'ai analysé les données de l'incident afin d'améliorer la structure de mon dispositif de refroidissement."
L18_1.m_Talk_FRA = L19_1
