L23_1 = "HORIZON_ACT2_INTERLUDE1@72#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 72
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 3500201
L22_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L22_1.m_Pos = "L"
L23_1 = "디자인은 햄스워스에게 대시의 덩실이를 참고해 달라고 했죠."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "デザインはダッシュのふわりを参考にしてほしいとヘムズワースに依頼しました。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "I've asked Helmsworth to refer to Dash's Dangler for the design."
L22_1.m_Talk_ENG = L23_1
L23_1 = "設計還請海姆斯沃斯參考黛西的鐮刀呢。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ฉันขอเฮล์มสเวิร์ธใช้แดงก์เลอร์ของแดชเป็นเรฟในการออกแบบ"
L22_1.m_Talk_THA = L23_1
L23_1 = "Tôi đã yêu cầu Helmsworth tham khảo lưỡi hái Dangler của Dash cho bản thiết kế."
L22_1.m_Talk_VTN = L23_1
L23_1 = "我和海姆斯沃思说外观设计可以参考黛西的发圈。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Für das Design habe ich Helmsworth gebeten, sich an Dashs Floaty zu orientieren."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Et pour le design, j'ai demandé à Helmsworth de s'inspirer du Dangler de Dash."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "HORIZON_ACT2_INTERLUDE1@73#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 73
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 3500201
L23_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "DASH_HORIZON_NULL_NULL"
L23_1.m_Pos = "R"
L23_1.m_Crash = 15
L24_1 = "앗, 정말! 덩실이랑 되게 닮았어요!"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "あ、本当だ！　ふわりに似てる！"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Oh! You're right! They look just like Dangler!"
L23_1.m_Talk_ENG = L24_1
L24_1 = "喔！真的！長得我的鐮刀好像！"
L23_1.m_Talk_TWN = L24_1
L24_1 = "โอ๊ะ! จริงด้วยค่ะ! มันดูเหมือนแดงก์เลอร์เลย!"
L23_1.m_Talk_THA = L24_1
L24_1 = "Ồ! Cô nói đúng! Chúng trông giống như Dangler!"
L23_1.m_Talk_VTN = L24_1
L24_1 = "啊，真的耶！看起来很像黛西的发圈！"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Oh! Hast Recht! Er sieht genauso aus wie Floaty!"
L23_1.m_Talk_DEU = L24_1
L24_1 = "Oh, c'est vrai ! C'est mon Dangler tout craché !"
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "HORIZON_ACT2_INTERLUDE1@74#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 74
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 3500201
L24_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_Face = "UNIT_PRIDE"
L24_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L24_1.m_Pos = "L"
L25_1 = "그렇습니다. 성능 면에서도 종전에 비해 냉각 효율이 약 17% 향상되었죠."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "そうです。性能面でも従来に比べて冷却効率が約17％向上しました。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Precisely. Their cooling performance has improved by approximately 17%."
L24_1.m_Talk_ENG = L25_1
L25_1 = "沒錯，冷卻效能也比之前提升約17%。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ถูกต้องค่ะ ประสิทธิภาพในการทำความเย็นเพิ่มขึ้นประมาณ 17% เลยนะคะ"
L24_1.m_Talk_THA = L25_1
L25_1 = "Đúng. Hiệu suất làm mát của chúng đã được cải thiện khoảng 17%."
L24_1.m_Talk_VTN = L25_1
L25_1 = "是的。性能方面也比以前的版本提高了17%的冷却效率。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Genau. Auch die Kühlleistung hat sich um ca. 17 % verbessert."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Exactement. Grâce à ça, les performances de mon dispositif de refroidissement ont augmenté d'environ 17 %."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
