L27_1 = "HORIZON_ACT2_INTERLUDE1@76#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 76
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 3500201
L26_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "UNIT_SERIOUS"
L26_1.m_Face = L27_1
L26_1.m_CharStrID = "RITA_HORIZON_NULL_NULL"
L26_1.m_Pos = "C"
L27_1 = "집어치워. 이 망할 꼬맹이에 너까지 엉겨붙으면 다들 날 어린이집 인솔 교사로 볼 테니까."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "いい加減にしろ。このクソガキに加えてお前までベタベタしてきたら、周りから私が幼稚園の先生だと思われるだろ。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Not a chance. Everyone will think I'm a preschool teacher if you tag along too. I've already got my hands full with the kid."
L26_1.m_Talk_ENG = L27_1
L27_1 = "還是算了，一個臭小鬼再加上你，這樣黏著我，大家會以為我是幼稚園老師吧。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ไม่มีทางซะล่ะ ถ้าเธอไปด้วยใครๆ คงนึกว่าฉันเป็นครูอนุบาล พวกเด็กๆ ทำฉันวุ่นไปหมดละ"
L26_1.m_Talk_THA = L27_1
L27_1 = "Đừng có mơ. Mọi người sẽ nghĩ tôi là giáo viên mầm non nếu cô cũng đi cùng. Một đứa thôi cũng đã đủ lắm rồi."
L26_1.m_Talk_VTN = L27_1
L27_1 = "还是放弃吧。这个小不点再加上你的话，别人看我都会以为是幼儿园的老师。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Vergiss es. Jeder wird mich für eine Kindergärtnerin halten, wenn dieses Kind mich schon begleitet und du auch noch dazukommst."
L26_1.m_Talk_DEU = L27_1
L27_1 = "N'y pense même pas. De quoi j'aurais l'air moi, à me traîner deux gamines partout avec moi ? C'est déjà assez compliqué comme ça avec une seule."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
