L30_1 = "HORIZON_ACT2_INTERLUDE1@79#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 79
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 3500201
L29_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_Face = "UNIT_IDLE"
L29_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L29_1.m_Pos = "L"
L30_1 = "제 외관은 휴먼 기준으로 그렇게 어려 보이지 않습니다."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "私の外見はヒューマンの基準でそこまで幼く見えません。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "But my exterior does not appear so young based on human standards."
L29_1.m_Talk_ENG = L30_1
L30_1 = "我的外表以人類的標準來說，看起來應該沒有很年輕。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "แต่เทียบกับมาตรฐานมนุษย์แล้วภายนอกฉันดูไม่เด็กเลยนะคะ"
L29_1.m_Talk_THA = L30_1
L30_1 = "Nhưng bề ngoài của tôi không có non nớt như vậy dựa trên tiêu chuẩn của con người."
L29_1.m_Talk_VTN = L30_1
L30_1 = "我的外观以人类的标准来看应该不算年幼吧。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Aber nach menschlichen Maßstäben wirkt mein Äußeres nicht so jung."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Selon les critères humains, mon apparence n'est pourtant pas si juvénile."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
