L32_1 = "HORIZON_ACT2_INTERLUDE1@81#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 81
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 3500201
L31_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_CharStrID = "DASH_HORIZON_NULL_NULL"
L31_1.m_Pos = "R"
L32_1 = "사실은 여기 이사 왔을 때 동네 어른 분이 대표님에 대해 물어 보시더라고요."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "実は、ここに引っ越してきた時に近所の人から代表について聞かれたんです。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Actually, someone in the neighborhood asked me about you when we moved here."
L31_1.m_Talk_ENG = L32_1
L32_1 = "其實在我們搬來這裡時，附近的大人有問起BOSS的事。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "จริงๆ ตอนเราย้ายมาที่นี่กัน ก็มีคนแถวนี้มาถามเรื่องคุณนะคะ"
L31_1.m_Talk_THA = L32_1
L32_1 = "Thực ra, có người trong khu phố đã hỏi cháu về cô khi chúng ta chuyển đến đây."
L31_1.m_Talk_VTN = L32_1
L32_1 = "可是我们刚搬来的时候，社区里的老人曾经问过我和BOSS是什么关系。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Ehrlich gesagt hat jemand aus der Nachbarschaft etwas über dich gefragt, als wir hierher gezogen sind."
L31_1.m_Talk_DEU = L32_1
L32_1 = "À vrai dire boss, quand on est arrivées ici..."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "HORIZON_ACT2_INTERLUDE1@82#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 82
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 3500201
L32_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "DASH_HORIZON_NULL_NULL"
L32_1.m_Pos = "R"
L33_1 = "그 예쁘장하게 생긴 애랑 언니 동생 사이냐고요."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "あの可愛らしい子は姉妹なのって。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "They asked if I'm sisters with \"that pretty girl.\""
L32_1.m_Talk_ENG = L33_1
L33_1 = "他們問說，那個可可愛愛的小朋友和姊姊是什麼關係？"
L32_1.m_Talk_TWN = L33_1
L33_1 = "พวกเขาถามว่าฉันเป็นพี่น้องกับ \"สาวสวยคนนั้นรึเปล่า\""
L32_1.m_Talk_THA = L33_1
L33_1 = "Họ hỏi cháu có phải là chị em của\"cô gái xinh đẹp đó không.\""
L32_1.m_Talk_VTN = L33_1
L33_1 = "还问我：“那个看起来很漂亮的小孩子和你是姐妹吗？”"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Und zwar, ob das hübsche Mädchen meine Schwester sei."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Les vieux du quartier m'ont demandé si nous étions sœurs, toi et moi."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "HORIZON_ACT2_INTERLUDE1@83#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 83
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 3500201
L33_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L33_1.m_bWaitClick = true
