L33_1.m_Face = "UNIT_PRIDE"
L33_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L33_1.m_Pos = "L"
L34_1 = "물론 제가 언니인 줄 알았겠죠."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "もちろん私のことがお姉ちゃんで、"
L33_1.m_Talk_JPN = L34_1
L34_1 = "They must think I'm the older sister, of course."
L33_1.m_Talk_ENG = L34_1
L34_1 = "他們一定以為我是姊姊吧。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "พวกเขาคงคิดว่าฉันเป็นพี่สาวคุณน่ะค่ะ แน่นอนเลย"
L33_1.m_Talk_THA = L34_1
L34_1 = "Tất nhiên họ nghĩ cháu là chị gái."
L33_1.m_Talk_VTN = L34_1
L34_1 = "当然，他以为我是姐姐。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Sie halten mich bestimmt für die ältere Schwester."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Ils devaient penser que j'étais l'aînée, naturellement."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
