L35_1 = "다들 대표님이 동생인 줄 아셨대요!"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "みんな代表が妹だと思っていたらしいです！"
L34_1.m_Talk_JPN = L35_1
L35_1 = "They all thought you're the younger one!"
L34_1.m_Talk_ENG = L35_1
L35_1 = "大家都以為BOSS是妹妹！"
L34_1.m_Talk_TWN = L35_1
L35_1 = "พวกเขาคิดว่าคุณเป็นน้องสาวค่ะ!"
L34_1.m_Talk_THA = L35_1
L35_1 = "Còn cô thì họ đều tưởng là em gái!"
L34_1.m_Talk_VTN = L35_1
L35_1 = "别人都以为BOSS才是妹妹！"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Alle dachten, du wärst die Jüngere von uns beiden!"
L34_1.m_Talk_DEU = L35_1
L35_1 = "Raté ! Ils étaient tous persuadés que tu étais ma petite sœur, hé hé !"
L34_1.m_Talk_FRA = L35_1
