L40_1 = "어떡해요, 언니? 대표님이 많이 실망한 것 같은데요?"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "どうしましょう？　代表が凹んでいます！"
L39_1.m_Talk_JPN = L40_1
L40_1 = "What should I do, Rita? The boss looks super disappointed."
L39_1.m_Talk_ENG = L40_1
L40_1 = "姊姊怎麼辦？BOSS好像很失望的樣子？"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ทำไงดีคะริตา? บอสดูใจร้าวสุดอะไรสุดเลยค่ะ"
L39_1.m_Talk_THA = L40_1
L40_1 = "Cháu nên làm gì đây, Rita? Bà chủ trông siêu thất vọng."
L39_1.m_Talk_VTN = L40_1
L40_1 = "怎么办啊，姐姐？BOSS看起来很失望啊？"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Oh je, Rita! Unsere Vorsitzende sieht total enttäuscht aus."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Qu'est-ce que je dois faire, Rita ? Je crois que j'ai vexé la boss..."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "HORIZON_ACT2_INTERLUDE1@90#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 90
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 3500201
L40_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_CharStrID = "RITA_HORIZON_NULL_NULL"
L40_1.m_Pos = "R"
L41_1 = "그러게 왜 괜히 끼어들어서 그래."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "まったく余計なこと言いやがって。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "This one's on you for butting in."
L40_1.m_Talk_ENG = L41_1
L41_1 = "所以說你幹嘛哪壺不開提哪壺。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "อันนี้เธอก็แส่หาเรื่องเองนะ"
L40_1.m_Talk_THA = L41_1
L41_1 = "Tại cháu cả thôi."
L40_1.m_Talk_VTN = L41_1
L41_1 = "所以，你为什么要插嘴啊。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Du hättest dich eben nicht einmischen sollen."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Il fallait vraiment que tu viennes mettre ton grain de sel comme ça ?"
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "HORIZON_ACT2_INTERLUDE1@91#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 91
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 3500201
L41_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_CharStrID = "RITA_HORIZON_NULL_NULL"
L41_1.m_Pos = "R"
L42_1 = "내버려 둬. 금방 괜찮아지겠지."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "ほっとけ。どうせ機嫌はすぐ直るだろ。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Just let her be. I'm sure she'll be fine in no time."
L41_1.m_Talk_ENG = L42_1
L42_1 = "別管她，很快就會沒事的。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ปล่อยนางเถอะ แป๊บๆ ก็เหมือนเดิมเอง"
L41_1.m_Talk_THA = L42_1
L42_1 = "Cứ kệ cô ấy. Ta chắc rằng cô ấy sẽ ổn trong thời gian ngắn thôi."
L41_1.m_Talk_VTN = L42_1
L42_1 = "别管她。过阵子就好了。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Lass gut sein. Ich bin sicher, dass das gleich vorbeigeht."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Bah, laisse-la tranquille. Ça va pas durer."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "HORIZON_ACT2_INTERLUDE1@92#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 92
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 3500201
L42_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_Face = "UNIT_SURPRISE"
L42_1.m_CharStrID = "DASH_HORIZON_NULL_NULL"
L42_1.m_Pos = "L"
L42_1.m_Crash = 15
L43_1 = "으앙, 그러면 안 돼요! 같은 사무소 사람들끼리 사이 좋게 지내야죠!"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "ええ、ダメですよ？　同じ事務所の仲間なんだから仲良くしないと！"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Come on, we can't do that! We're on the same team! We should all get along!"
L42_1.m_Talk_ENG = L43_1
L43_1 = "嗚嗚，不可以啦。大家都在同一間公司，要相親相愛才可以！"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ไม่เอาสิ เราทำแบบนั้นไม่ได้นะคะ! เราทีมเดียวกันนี่นา! เราต้องเข้ากันให้ดีสิ!"
L42_1.m_Talk_THA = L43_1
L43_1 = "Thôi nào, chúng ta không thể làm thế! Chúng ta ở cùng một nhóm mà! Tất cả chúng ta nên hòa thuận với nhau!"
L42_1.m_Talk_VTN = L43_1
L43_1 = "唔，不能这样！作为事务所的同事，我们要友好相处！"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Komm schon, das geht nicht! Wir müssen uns gut vertragen, denn wir sind Kollegen!"
L42_1.m_Talk_DEU = L43_1
L43_1 = "Mais non, dis pas ça ! On forme une équipe, il faut qu'on se serre les coudes !"
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "HORIZON_ACT2_INTERLUDE1@93#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 93
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 3500201
L43_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_CharStrID = "RITA_HORIZON_NULL_NULL"
L43_1.m_Pos = "R"
L44_1 = "사이 좋게? 넌 여기가 무슨 학교인 줄 알아?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "仲良く？　お前はここを学校と勘違いしてんじゃないか？"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Get along? You think you're in school or something?"
L43_1.m_Talk_ENG = L44_1
L44_1 = "相親相愛？你以為這裡是學校嗎？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "เข้ากันให้ดี? นี่คิดว่าตัวเองอยู่ในโรงเรียนรึไงนี่?"
L43_1.m_Talk_THA = L44_1
L44_1 = "Hòa thuận? Cháu nghĩ cháu đang đi học hay sao?"
L43_1.m_Talk_VTN = L44_1
L44_1 = "友好相处！你以为这里是学校吗？"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Gut vertragen? Glaubst du, wir sind hier in der Schule?"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Se serrer les coudes ? Tu te crois où exactement, à l'école ?"
L43_1.m_Talk_FRA = L44_1
