L3_1.m_Pos = "L"
L4_1 = "……성분 분석 결과, 도금된 세공품이군요."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "……成分分析の結果によると、メッキ加工された細工品ですね。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Composition analysis indicates this is a gold-plated ornament of some kind."
L3_1.m_Talk_ENG = L4_1
L4_1 = "……成分分析結果，是鍍金的手工藝品。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "การสังเคราะห์องค์ประกอบระบุวว่านี่เป็นเครื่องประดับเคลือบทองอะไรทำนองนั้น"
L3_1.m_Talk_THA = L4_1
L4_1 = "Phân tích thành phần chỉ ra rằng đây là một loại đồ vật trang trí mạ vàng."
L3_1.m_Talk_VTN = L4_1
L4_1 = "……分析结果显示，这是镀金加工品。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Die Bauteilanalyse zeigt, dass es sich um ein goldplattiertes Werkstück handelt."
L3_1.m_Talk_DEU = L4_1
L4_1 = "... L'analyse structurelle indique un objet décoratif en métal."
L3_1.m_Talk_FRA = L4_1
