L5_1 = "HORIZON_ACT2_INTERLUDE1@104#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 104
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 3500201
L4_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
