L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L4_1.m_Pos = "L"
L5_1 = "저에게는 이제 불필요한 물건입니다. 복장 이전에 제 프레임의 근본적인 결함을 발견했으니까요."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "私にはもう不要な物です。服装以前に、私のフレームの根本的な欠陥を発見したので。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "I have no need for such a trinket now. I've discovered a fundamental defect in my frame that supersedes the matter of attire."
L4_1.m_Talk_ENG = L5_1
L5_1 = "我不需要這個，因為問題不在穿著，而是我這副軀殼本身的缺陷。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ตอนนี้ฉันไม่อยากได้ของอะไรจุ๊กจิ๊กนะคะ ฉันพบมีว่าตำหนิพื้นฐานในเฟรมตัวเองมากินที่เสื้อผ้าของฉัน"
L4_1.m_Talk_THA = L5_1
L5_1 = "Bây giờ tôi không cần một món đồ nữ trang rẻ tiền như vậy nữa. Tôi đã phát hiện ra một khiếm khuyết quan trọng trong bộ khung của mình thay vì vấn đề trang phục."
L4_1.m_Talk_VTN = L5_1
L5_1 = "这东西现在已经对我没用了。问题不是出在穿着上，而是这副躯壳存在着根本性的缺陷。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Jetzt brauche ich es nicht mehr. Abgesehen von dem Outfit liegt der grundlegende Fehler in meinem Rahmen."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Cette babiole ne m'est d'aucune utilité pour le moment. Mon armature dispose d'un défaut fondamental que je dois corriger."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
