L10_1 = "ダッシュがそこまで言うなら、わかりました。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Very well, Dash. If you insist."
L9_1.m_Talk_ENG = L10_1
L10_1 = "既然黛西那麼說，那好吧。"
L9_1.m_Talk_TWN = L10_1
