L18_1.m_fWaitTime = 0
L18_1.m_CharStrID = "RITA_HORIZON_NULL_NULL"
L18_1.m_Pos = "R"
L19_1 = "나는 왜 또 끌어들여, 이 망할 꼬맹아."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "私は巻き込むなよ、ガキ。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Don't drag me into this, you dratted broad."
L18_1.m_Talk_ENG = L19_1
L19_1 = "你這臭小鬼，幹嘛又把我扯進來。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ไม่ต้องลากฉันไปเกี่ยวเลยนะ ยัยตัวแสบ"
L18_1.m_Talk_THA = L19_1
L19_1 = "Đừng lôi ta vào chuyện này, đồ ngốc."
L18_1.m_Talk_VTN = L19_1
L19_1 = "别把我扯进来，你这个臭小不点。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Lass mich aus dem Spiel, du nerviger Knirps."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Laisse-moi en dehors de tout ça, imbécile."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "HORIZON_ACT2_INTERLUDE1@119#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 119
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 3500201
L19_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_Face = "UNIT_PRIDE"
L19_1.m_CharStrID = "DASH_HORIZON_NULL_NULL"
L19_1.m_Pos = "L"
L19_1.m_Crash = 20
L20_1 = "도와 주세요, 언니! 언니 어깨에 우리 사무소의 평화가 걸려 있어요!"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "何か言ってくださいよ！　お姉ちゃんの一言にうちの事務所の今後がかかっていますよ！？"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Work with me here, Rita! The peace of our workplace rests on your shoulders!"
L19_1.m_Talk_ENG = L20_1
L20_1 = "姊姊快幫我說句話！姊姊現在可是肩負著這間辦公室的和平！"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ช่วยกันหน่อยสิคะริตา! ชะตาความสงบของที่ทำงานอยู่ในมือคุณแล้วนะคะ!"
L19_1.m_Talk_THA = L20_1
L20_1 = "Phối hợp với cháu chút đi nào, Rita! Sự yên bình của nơi làm việc của chúng ta dựa cả vào cô đấy."
L19_1.m_Talk_VTN = L20_1
L20_1 = "帮帮我吧，姐姐！守护我们公司和平的重任在你的手上！"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Hilf uns, Rita! Die Zukunft unseres Söldnerbüros hängt von dir ab!"
L19_1.m_Talk_DEU = L20_1
L20_1 = "Allez quoi, un petit effort ! Maintenir une bonne ambiance au bureau, c'est vital !"
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "HORIZON_ACT2_INTERLUDE1@120#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 120
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 3500201
L20_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_CharStrID = "DASH_HORIZON_NULL_NULL"
L20_1.m_Pos = "L"
L21_1 = "분명히 대표님도 저희 없는 동안 혼자 지내기 외로워서 저러시는 걸 거예요!"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "きっと代表も私たちがいない間、一人で過ごすのが寂しいからだと思いますよ。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "I'm sure the boss is being like that because she gets lonely without us!"
L20_1.m_Talk_ENG = L21_1
L21_1 = "一定是因為我們不在時，BOSS太孤單才會這樣的 ！"
L20_1.m_Talk_TWN = L21_1
L21_1 = "ฉันมั่นใจค่ะว่าบอสเป็นแบบนั้นเพราะเธอเหงาตอนเราไม่อยู่!"
L20_1.m_Talk_THA = L21_1
L21_1 = "Cháu chắc rằng bà chủ như thế là bởi vì cô ấy sẽ cô đơn khi không có chúng ta!"
L20_1.m_Talk_VTN = L21_1
L21_1 = "BOSS也一定是因为我们不在的时候太孤独，所以才这样的！"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Unsere Vorsitzende verhält sich bestimmt so, weil sie nicht gerne einsam ist, während wir weg sind!"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Si la boss agit ainsi, c'est parce qu'elle doit s'ennuyer toute seule ici à longueur de journée."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
