L23_1 = "HORIZON_ACT2_INTERLUDE1@122#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 122
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 3500201
L22_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_Face = "UNIT_IDLE"
L22_1.m_CharStrID = "RITA_HORIZON_NULL_NULL"
L22_1.m_Pos = "R"
L23_1 = "그래. 무서워 죽겠다. 주머니에 동전이라도 있으면 바로 넘겨 줬겠어."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "そうだな、怖くてゾッとする。ポケットに小銭が入っていれば全部渡してやりたいぐらいだ。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Fine. Ooh, I'm so scared. If I had any change in my pocket, I would've forked it over in a heartbeat."
L22_1.m_Talk_ENG = L23_1
L23_1 = "嘿啦，有夠可怕的。 如果口袋有硬幣，我一定會馬上掏出來給你。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ก็ได้ โอ้ย กลัวจะแย่แล้วแม่ นี่ถ้ามีเศษตังค์ในกระเป๋าฉันยอมเอาให้หมดแล้ว"
L22_1.m_Talk_THA = L23_1
L23_1 = "Rồiiii. Ooh, tôi sợ quá. Nếu tôi có bất kỳ xu nào trong túi của mình, tôi sẽ nộp nó ngay lập tức."
L22_1.m_Talk_VTN = L23_1
L23_1 = "好吧。我承认你看起来很凶。如果我兜里有钱，一定会马上给你。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Ja, ich sterbe vor Angst. Hätte ich Münzen in der Hosentasche, würde ich sie sofort rausrücken."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Bon. Bouh, je suis terrifiée. J'ai si peur que je serais prête à vider mes poches sur-le-champ. Dommage qu'elles soient vides..."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
