L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 125
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 3500201
L25_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_Face = "UNIT_SURPRISE"
L25_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L25_1.m_Pos = "C"
L26_1 = "놀랍군요. 항상 허세를 부리던 리타가 벌벌 떨고 있습니다."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "これは驚きですね。いつも虚勢を張るリタが恐怖に怯えています。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Incredible. The perpetually haughty Rita is trembling in fear."
L25_1.m_Talk_ENG = L26_1
L26_1 = "這麼厲害，氣勢那麼強的麗塔竟然在發抖。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "เหลือเชื่อจริงๆ คนโอหังอย่างริตากำลังกลัวจนตัวสั่น"
L25_1.m_Talk_THA = L26_1
L26_1 = "Tuyệt lắm. Rita kiêu ngạo đang run lên vì sợ hãi."
L25_1.m_Talk_VTN = L26_1
L26_1 = "真惊人。每次都虚张声势的丽塔竟然被我吓到了。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Erstaunlich. Rita zittert vor Angst, obwohl sie sonst immer so arrogant ist."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Incroyable. Rita la stoïque qui tremble de peur..."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
