L29_1 = "R_M_I"
L28_1.m_Pos = L29_1
L28_1.m_Crash = 30
L29_1 = "어? 대표님, 갑자기 서랍장은 왜 뒤지세요?"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "あれ？　代表、急に引き出しを開けて何を探しているんですか？"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Huh? What are you looking through the drawers for all of a sudden?"
L28_1.m_Talk_ENG = L29_1
L29_1 = "BOSS，你翻抽屜幹嘛？"
L28_1.m_Talk_TWN = L29_1
L29_1 = "หือ ทำไมอยู่ๆ คุณก็หาอะไรในลิ้นชักละคะ?"
L28_1.m_Talk_THA = L29_1
L29_1 = "Huh? Đột nhiên cô nhìn vào ngăn kéo làm cái gì thế?"
L28_1.m_Talk_VTN = L29_1
L29_1 = "咦？BOSS，你为什么要突然去翻书柜？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Huch? Warum kramst du auf einmal in der Schublade?"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Hein ? Qu'est-ce que tu cherches dans ce tiroir, tout d'un coup ?"
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "HORIZON_ACT2_INTERLUDE1@129#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 129
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 3500201
L29_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L29_1.m_Pos = "L"
L30_1 = "리타의 허세를 꺾은 역사적인 순간을 기록으로 남기기 위해서죠."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "リタを怯えさせた歴史的な瞬間を記録として残すためです。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "To document this historic moment of finally conquering Rita's pride, of course."
L29_1.m_Talk_ENG = L30_1
L30_1 = "我要紀錄下削弱麗塔氣勢的這個歷史性的一刻。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "แน่อยู่แล้ว ก็จะได้บันทึกเรื่องนี้เป็นช่วงเวลาประวัติศาสตร์ที่ในที่สุดก็พิชิตความทระนงของริตาได้นะสิ"
L29_1.m_Talk_THA = L30_1
L30_1 = "Tất nhiên là để ghi lại khoảnh khắc lịch sử hạ gục niềm kiêu hãnh của Rita rồi."
L29_1.m_Talk_VTN = L30_1
L30_1 = "我想将打破丽塔虚张声势的历史性瞬间记录下来。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Ich will diesen historischen Moment dokumentieren, in dem ich Rita gezeigt habe, wo es langgeht."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Nous sommes en train de vivre un moment historique. Je dois absolument l'enregistrer."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
