L32_1 = "HORIZON_ACT2_INTERLUDE1@131#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 131
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 3500201
L31_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Face = "UNIT_IDLE"
L31_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L31_1.m_Pos = "C"
L32_1 = "이건 채무자에게서 담보로 받았던 디지털 카메라입니다."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "これは債務者から担保でもらったデジタルカメラです。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "I've secured this digital camera from a debtor as collateral."
L31_1.m_Talk_ENG = L32_1
L32_1 = "這是債務人拿來作抵押的數位相機。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ฉันได้กล้องดิจิทัลนี่มาเป็นหลักประกันจากเจ้าหนี้"
L31_1.m_Talk_THA = L32_1
L32_1 = "Tôi đã cất chiếc máy ảnh kỹ thuật số này từ một con nợ làm tài sản thế chấp."
L31_1.m_Talk_VTN = L32_1
L32_1 = "这是以前债务者抵押的数码相机。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Das ist die Digicam, die ich von einem Schuldner als Pfand bekommen habe."
L31_1.m_Talk_DEU = L32_1
L32_1 = "C'est le moment d'utiliser cet appareil photo analogique que j'ai reçu en gage auprès d'un client."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "HORIZON_ACT2_INTERLUDE1@132#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 132
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 3500201
