L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L32_1.m_Pos = "C"
L33_1 = "애석하게도 현재는 수명이 다해 작동하지 않는군요."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "残念ながら現在は寿命が尽きて作動しません。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Regrettably, it is currently too antiquated to function."
L32_1.m_Talk_ENG = L33_1
L33_1 = "有點可惜，它的壽命已盡無法使用。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "น่าเสียดายนะคะที่มันโบราณจนใช้งานไม่ได้"
L32_1.m_Talk_THA = L33_1
L33_1 = "Đáng tiếc, nó hiện đã quá cổ lỗ nên không hoạt động."
L32_1.m_Talk_VTN = L33_1
L33_1 = "很遗憾现在因为老化无法正常使用。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Leider ist sie nun zu alt und funktioniert nicht mehr."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Malheureusement, on dirait qu'il a trop pris la poussière. Il est hors d'état."
L32_1.m_Talk_FRA = L33_1
