L35_1.m_Face = "UNIT_LAUGH"
L35_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L36_1 = "L_M_I"
L35_1.m_Pos = L36_1
L36_1 = "그렇게 되었으니 수리를 부탁하겠습니다. 리타."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "だから修理をお願いします、リタ。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "As such, I must ask for your assistance in repairing it, Rita."
L35_1.m_Talk_ENG = L36_1
L36_1 = "麗塔，要麻煩你修理一下。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ดังนั้น ฉันคงต้องขอให้คุณช่วยซ่อมมันหน่อยค่ะริตา"
L35_1.m_Talk_THA = L36_1
L36_1 = "Vì vậy, tôi phải yêu cầu sự hỗ trợ của cô để sửa chữa nó, Rita."
L35_1.m_Talk_VTN = L36_1
L36_1 = "既然这样，请你修理一下吧。丽塔。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Deshalb vertraue ich dir die Reparatur an, Rita."
L35_1.m_Talk_DEU = L36_1
L36_1 = "J'ai besoin de votre aide pour le réparer, Rita."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "HORIZON_ACT2_INTERLUDE1@136#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 136
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 3500201
L36_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_CharStrID = "RITA_HORIZON_NULL_NULL"
L36_1.m_Pos = "R"
L37_1 = "싸잡아서 분해해 버리기 전에 내 눈앞에서 치워."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "お前ごとまとめて分解する前にしまっておけ。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Get that thing out of my face before I disassemble, it along with you."
L36_1.m_Talk_ENG = L37_1
L37_1 = "我勸你最好把它拿開，否則我連你一起拆掉。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "เอามันไปให้พ้นหน้าฉันก่อนฉันจะรื้อมันไปพร้อมเธอเลยนะ"
L36_1.m_Talk_THA = L37_1
L37_1 = "Lấy thứ đó ra khỏi mặt tôi trước khi tôi rã-nó-ra, cùng với cô đấy."
L36_1.m_Talk_VTN = L37_1
L37_1 = "在我把这东西踩得稀巴烂之前快从我眼前拿开。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Nimm das Ding vor meinen Augen weg, bevor ich euch allesamt zerlege."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Ôte-moi ce truc du regard ou je le fais disparaître, et toi avec !"
L36_1.m_Talk_FRA = L37_1
