L40_1 = "UNIT_DESPAIR"
L39_1.m_Face = L40_1
L39_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L39_1.m_Pos = "C"
L40_1 = "저는 더 이상 기동할 이유를 상실했습니다. 대시."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "私はこれ以上起動する理由を失いました、ダッシュ。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "I have lost all purpose for my continued operation, Dash."
L39_1.m_Talk_ENG = L40_1
L40_1 = "黛西，我失去繼續運作下去的理由 。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ฉันหมดสิ้นวัตถุประสงค์จะดำเนินงานต่อแล้วค่ะแดช"
L39_1.m_Talk_THA = L40_1
L40_1 = "Tôi đã mất hết mục đích để tiếp tục hoạt động rồi, Dash."
L39_1.m_Talk_VTN = L40_1
L40_1 = "啊，黛西，我已经失去了继续运作的理由。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Ich habe jegliche Gründe für meine fortwährende Inbetriebnahme verloren, Dash."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Je ne vois plus de raison de continuer les opérations. Dash..."
L39_1.m_Talk_FRA = L40_1
