L40_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L40_1.m_Pos = "C"
L41_1 = "저를 이 저주 받을 프레임과 함께 금고에 넣어 깊은 바다 속으로 빠뜨려 주십시오."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "私をこの役に立たないフレームと一緒に金庫に入れて深い海の中に沈めてください。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Please lock me in a safe with this cursed frame and toss it into the ocean."
L40_1.m_Talk_ENG = L41_1
L41_1 = "請把我和這個受詛咒的軀殼，一起放進保險箱裡，扔到深海裡去吧。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ช่วยล็อกไว้ในตู้เซฟกับเฟรมต้องสาปนี้แล้วเอาไปโยนทิ้งทะเลทีนะคะ"
L40_1.m_Talk_THA = L41_1
L41_1 = "Làm ơn nhốt tôi trong một cái két sắt với bộ khung bị nguyền rủa này và ném nó xuống đại dương đi."
L40_1.m_Talk_VTN = L41_1
L41_1 = "将我和这受到诅咒的躯壳一起锁进金库沉入海底的深渊吧。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Bitte sperr mich mit diesem verfluchten Rahmen in einen Safe und wirf ihn ins Meer."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Enfermez-moi dans un coffre avec cette armature, et jetez-moi dans l'océan."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
