L43_1.m_Face = "UNIT_SURPRISE"
L43_1.m_CharStrID = "DASH_HORIZON_NULL_NULL"
L44_1 = "R_M_I"
L43_1.m_Pos = L44_1
L44_1 = "아앗! 언니! 한 번만요! 이러다 대표님이 죽어 버려요!"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "ああ、お姉ちゃん！　一度だけでいいので！　このままじゃ代表が死んでしまいます！"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Aw! Rita! Come on! The boss just might die like this!"
L43_1.m_Talk_ENG = L44_1
L44_1 = "唉唷姊姊！拜託啦！這樣下去BOSS會死掉的！"
L43_1.m_Talk_TWN = L44_1
L44_1 = "โอ๊ย! ริตา! ไม่เอาสิ! บอสจะมาตายแบบนี้ไม่ได้นะคะ!"
L43_1.m_Talk_THA = L44_1
L44_1 = "Ồ! Rita! Thôi nào! Bà chủ có thể sẽ chết nếu chúng ta cứ thế này mất!"
L43_1.m_Talk_VTN = L44_1
L44_1 = "哎呀，姐姐！就这一次！这样下去BOSS会难受死的！"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Oh nein! Rita! Nur einmal, bitte! Sonst stirbt die Vorsitzende!"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Je t'en prie, Rita ! Tu vois bien que la boss est sérieuse, non ?"
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
