L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 145
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 3500201
L45_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_Face = "UNIT_HATE"
L45_1.m_CharStrID = "RITA_HORIZON_NULL_NULL"
L45_1.m_Pos = "C"
L46_1 = "빌어먹을……. 어떻게 되어먹은 인공지능이 카메라 하나 손볼 줄도 몰라."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "くそ……人工知能のくせにカメラも直せないのか？"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Damn it… What kind of an A.I. doesn't even know how to repair a camera?"
L45_1.m_Talk_ENG = L46_1
L46_1 = "討厭……身為人工智慧怎麼會連修個相機都不會。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "บ้าจริงเฮ้ย... เอไอพรรค์ไหนมันไม่รู้แม้แต่วิธีซ่อมกล้องเนี่ย"
L45_1.m_Talk_THA = L46_1
L46_1 = "Chết tiệt… Loại AI nào thậm chí còn không biết sửa máy ảnh cơ chứ?"
L45_1.m_Talk_VTN = L46_1
L46_1 = "真是该死……人工智能竟然连一个相机都不会修。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Verdammt ... du bist eine KI und kannst nicht mal eine Kamera reparieren?"
L45_1.m_Talk_DEU = L46_1
L46_1 = "Tss... Même pas fichue de réparer un appareil photo ? Tu parles d'une « intelligence » artificielle..."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "HORIZON_ACT2_INTERLUDE1@146#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 146
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 3500201
