L46_1.m_StartFXSoundName = L47_1
L47_1 = "RITA_HORIZON_NULL_ON"
L46_1.m_CharStrID = L47_1
L46_1.m_Pos = "C"
L47_1 = "와라. 오메르타."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "オメルタ。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Come, Omerta."
L46_1.m_Talk_ENG = L47_1
L47_1 = "來吧，奧梅爾塔。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "จงมา โอเมอร์ตา"
L46_1.m_Talk_THA = L47_1
L47_1 = "Ra đi, Omerta."
L46_1.m_Talk_VTN = L47_1
L47_1 = "出来吧，莫塔。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Komm her, Omerta."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Viens, Omerta."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "HORIZON_ACT2_INTERLUDE1@147#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 147
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 3500201
L47_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_Face = "UNIT_IDLE"
L47_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L47_1.m_Pos = "C"
L48_1 = "카메라 하나 수리하는 데 너무 비효율적인 것 아닙니까?"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "カメラ一つ修理するのに非効率的すぎますね。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Wouldn't that be an inefficiently excessive use of resources just to repair a camera?"
L47_1.m_Talk_ENG = L48_1
L48_1 = "不過是相機，有需要召喚奧梅爾塔嗎？"
L47_1.m_Talk_TWN = L48_1
L48_1 = "แค่ซ่อมกล้องดิจิทัลนี่ แบบนั้นจะไม่เป็นการใช้ทรัพยากรเกินขนาดโดยไม่ประสิทธิภาพเหรอคะ?"
L47_1.m_Talk_THA = L48_1
L48_1 = "Cô định dùng dao mổ trâu để giết gà đấy à?"
L47_1.m_Talk_VTN = L48_1
L48_1 = "为了修个相机召唤出莫塔，是不是太没效率了？"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Ist das nicht eine ineffiziente Art, um bloß eine Kamera zu reparieren?"
L47_1.m_Talk_DEU = L48_1
L48_1 = "Tout ça pour un simple appareil photo ? C'est du gaspillage de ressources, non ?"
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "HORIZON_ACT2_INTERLUDE1@148#Talk"
