L49_1 = "RITA_HORIZON_NULL_ON"
L48_1.m_CharStrID = L49_1
L48_1.m_Pos = "C"
L49_1 = "시끄러워, 고철. 집중하는 데 방해돼."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "うるさい、鉄くず。邪魔だからどけ。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Shut up, you piece of junk. I'm trying to focus here."
L48_1.m_Talk_ENG = L49_1
L49_1 = "閉嘴，廢鐵。不要吵我。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "หุบปากเลยไปยายเศษเหล็ก ฉันพยายามมีสมาธิอยู่นะ"
L48_1.m_Talk_THA = L49_1
L49_1 = "Im đi, đồ phế liệu. Tôi đang cố gắng tập trung đây."
L48_1.m_Talk_VTN = L49_1
L49_1 = "吵死了，你这块铁疙瘩。别妨碍我集中注意力。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Schnauze, Altmetall. Du störst mich bei der Konzentration."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Silence, le tas de ferraille. J'essaye de me concentrer."
L48_1.m_Talk_FRA = L49_1
