L3_1.m_BGFileName = "office_detect"
L3_1.m_Face = "UNIT_PRIDE"
L3_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L3_1.m_Pos = "C"
L4_1 = "그래도 마침 잘됐군요. 사진 찍어 줄 사람이 필요했습니다."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "でもちょうどよかったです。写真を取ってくれる人が必要だったので。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "I suppose it's for the best. We needed someone to take the picture for us, after all."
L3_1.m_Talk_ENG = L4_1
L4_1 = "不過也好，反正我們需要攝影師。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "หวังว่าจะคุ้มนะคะ เพราะเดี๋ยวเราก็ต้องมีคนถ่ายรูปให้เราด้วย"
L3_1.m_Talk_THA = L4_1
L4_1 = "Cũng được đấy. Sau cùng thì chúng ta cũng cần một người chụp ảnh chứ."
L3_1.m_Talk_VTN = L4_1
L4_1 = "不过这样也好。正好需要有人给我们照相。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Das trifft sich aber gut. Wir haben jemanden gebraucht, der das Foto für uns schießt."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Enfin je suppose que c'est un mal pour un bien. Il faut bien que quelqu'un nous prenne toutes les trois !"
L3_1.m_Talk_FRA = L4_1
