L7_1 = "UNIT_DESPAIR"
L6_1.m_Face = L7_1
L6_1.m_CharStrID = "DASH_HORIZON_NULL_NULL"
L6_1.m_Pos = "L"
L6_1.m_Crash = 15
L7_1 = "오메르타도 안 찍어 주면 섭섭해하지 않을까요?"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "オメルタも一緒に撮ってあげないと寂しがるんじゃないでしょうか？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "But don't you think Omerta will be sad if it gets left out of the photo?"
L6_1.m_Talk_ENG = L7_1
L7_1 = "奧梅爾塔沒入鏡的話不會難過嗎？"
L6_1.m_Talk_TWN = L7_1
L7_1 = "แต่โอเมอร์ตาจะไม่ว่าอะไรเหรอคะถ้าไม่ได้อยู่ในรูปด้วย?"
L6_1.m_Talk_THA = L7_1
L7_1 = "Nhưng cô có nghĩ rằng Omerta sẽ buồn nếu không có mặt trong ảnh không?"
L6_1.m_Talk_VTN = L7_1
L7_1 = "可是如果不给莫塔照相的话，它会不会失望呢？"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Omerta wäre bestimmt enttäuscht, wenn sie nicht auf das Foto darf."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Tu ne crois pas qu'Omerta va être triste de ne pas être sur la photo ?"
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "HORIZON_ACT2_INTERLUDE1@157#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 157
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 3500201
L7_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L7_1.m_Pos = "R"
L8_1 = "무척 예리한 지적이군요. 제 사고회로의 결함을 정확히 짚었습니다."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "とても鋭い指摘ですね。私の思考回路の欠陥を正確に指摘しました。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "A most acute observation. You've identified the flaw in my reasoning algorithm with pinpoint precision."
L7_1.m_Talk_ENG = L8_1
L8_1 = "你說的很對，準確地指出我思考迴路的問題。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "เป็นการสังเกตที่เฉียบแหลมมากค่ะ คุณพบข้อบกพร่องในอัลกอริทึมการให้เหตุผลของฉันด้วยความแม่นยำเป็นที่สุด"
L7_1.m_Talk_THA = L8_1
L8_1 = "Thật là quan sát sắc bén. Cháu đã xác định được lỗ hổng trong thuật toán lập luận của cô với độ chính xác tuyệt đối."
L7_1.m_Talk_VTN = L8_1
L8_1 = "你说的太对了。一针见血的正确指出我思维回路的缺陷。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Eine scharfe Beobachtung von dir. Du hast genau die Schwachstelle meines Denksystems aufgezeigt."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Bonne remarque, Dash. Vous avez identifié la faille dans mon système de raisonnement avec une étonnante précision."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "HORIZON_ACT2_INTERLUDE1@158#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 158
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 3500201
L8_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L8_1.m_Pos = "R"
L9_1 = "역시 대시는 유능합니다. 우리 회사의 직원이 될 자격이 있어요."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "やはりダッシュは有能です。我が社の社員になる資格があります。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "You are indeed most capable, Dash. You are worthy of working for this company."
L8_1.m_Talk_ENG = L9_1
L9_1 = "黛西果然很精明，有資格當我們公司的職員。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "คุณนี่มีความสามารถแท้ๆ เลยนะคะ ควรค่าแก่การทำงานที่บริษัทนี้จริงๆ ค่ะ"
L8_1.m_Talk_THA = L9_1
L9_1 = "Cháu thực sự là giỏi nhất, Dash. Cháu xứng đáng được làm việc cho công ty này."
L8_1.m_Talk_VTN = L9_1
L9_1 = "果然黛西很厉害。有成为我们公司职员的资格。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Dash hat es wirklich drauf. Sie hat es verdient, eine Mitarbeiterin unserer Firma zu sein."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Décidément, vous avez de la ressource. Vous êtes digne de travailler ici, à Horizon Finance."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
