L10_1 = "それは褒め言葉ですよね？　やったー！"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Was that a compliment? Yay!"
L9_1.m_Talk_ENG = L10_1
L10_1 = "這是稱讚吧？萬歲！"
L9_1.m_Talk_TWN = L10_1
L10_1 = "นั่นเป็นคำชมเหรอคะ? เย้!"
L9_1.m_Talk_THA = L10_1
L10_1 = "Đó có phải là một lời khen không? Yay!"
L9_1.m_Talk_VTN = L10_1
L10_1 = "这是在夸我吗？万岁!"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Das ist ein Kompliment, oder? Juhu!"
L9_1.m_Talk_DEU = L10_1
L10_1 = "C'est bien un compliment ? Youpi !"
