L12_1 = "UNIT_DESPAIR"
L11_1.m_Face = L12_1
L11_1.m_CharStrID = "RITA_HORIZON_NULL_NULL"
L11_1.m_Pos = "C"
L12_1 = "멍청한 소리는 적당히 하지."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "バカなことをいうのもほどほどにしろ。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Enough with the stupid chitchat."
L11_1.m_Talk_ENG = L12_1
L12_1 = "廢話說完沒有？"
L11_1.m_Talk_TWN = L12_1
L12_1 = "เลิกงุ้งงิ้งมุ้งมิ้งกันซะที"
L11_1.m_Talk_THA = L12_1
L12_1 = "Quá đủ với mấy trò ngu ngốc rồi."
L11_1.m_Talk_VTN = L12_1
L12_1 = "别说傻话了。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Genug Dumpfsinn geredet."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Assez de bavardages inutiles."
