L13_1 = "HORIZON_ACT2_INTERLUDE1@162#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 162
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 3500201
L12_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_Face = "UNIT_LAUGH"
L12_1.m_CharStrID = "RITA_HORIZON_NULL_NULL"
L12_1.m_Pos = "C"
L13_1 = "수리 끝났어. 타이머 맞춰 뒀으니까 렌즈 앞에 서."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "終わったぞ。タイマーは合わせておいたからカメラの前に立て。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "There, I fixed it. I've also set the timer, so stand in front of the lens."
L12_1.m_Talk_ENG = L13_1
L13_1 = "修理好了，計時器也調好了，來站在鏡頭前。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "อะ ฉันซ่อมให้ละ ตั้งเวลาให้แล้วด้วย เอ้า มาเข้ากล้องกัน"
L12_1.m_Talk_THA = L13_1
L13_1 = "Đó, tôi đã sửa nó xong rồi. Tôi cũng đã đặt hẹn giờ, vì vậy hãy đứng trước ống kính."
L12_1.m_Talk_VTN = L13_1
L13_1 = "修理完了。我设定了倒计时，快到镜头前面来。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Die Reparatur ist abgeschlossen. Ich habe den Timer eingestellt, also stellt euch vor die Kamera."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Voilà, c'est réparé. J'ai activé le retardateur, nous n'avons qu'a nous positionner devant l'objectif."
L12_1.m_Talk_FRA = L13_1
