L15_1.m_Face = "UNIT_SURPRISE"
L15_1.m_CharStrID = "DASH_HORIZON_NULL_NULL"
L15_1.m_Pos = "L"
L15_1.m_Crash = 30
L16_1 = "어? 언니, 이런 거 싫어하지 않았어요?"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "あれ、お姉ちゃんってこういうの苦手だったのでは？"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Huh? I thought you weren't a photo person, Rita."
L15_1.m_Talk_ENG = L16_1
L16_1 = "嗯？姊姊，你不是討厭這樣嗎？"
L15_1.m_Talk_TWN = L16_1
L16_1 = "หือ? ฉันนึกว่าคุณไม่ชอบถ่ายรูปซะอีกค่ะริตา"
L15_1.m_Talk_THA = L16_1
L16_1 = "Huh? Cháu đã tưởng là cô không thích chụp ảnh kia mà, Rita."
L15_1.m_Talk_VTN = L16_1
L16_1 = "啊？姐姐不是非常讨厌照相吗？"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Huch? Rita, ich dachte, du hasst es, für Fotos zu posieren."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Hein ? Je savais pas que t'aimais les photos, Rita !"
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "HORIZON_ACT2_INTERLUDE1@166#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 166
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 3500201
L16_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L16_1.m_Pos = "R"
L17_1 = "리타는 자기 감정에 솔직하지 못합니다."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "リタは自分の感情に素直ではありません。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Rita is rarely true to her feelings."
L16_1.m_Talk_ENG = L17_1
L17_1 = "麗塔無法坦率地表達自己的感覺。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ริตาไม่ค่อยแสดงความรู้สึกจริงๆ ออกมาหรอกค่ะ"
L16_1.m_Talk_THA = L17_1
L17_1 = "Rita hiếm khi sống thật với cảm xúc của mình."
L16_1.m_Talk_VTN = L17_1
L17_1 = "丽塔对自己的感情不够坦率。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Rita steht nie zu ihren Gefühlen."
L16_1.m_Talk_DEU = L17_1
L17_1 = "C'est parce qu'elle réprime ses sentiments derrière un mur d'intransigeance."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "HORIZON_ACT2_INTERLUDE1@167#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 167
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 3500201
L17_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L17_1.m_Pos = "R"
L18_1 = "단체 사진을 찍고 싶지만 체면 때문에 다른 사람이 제안해 주길 바라는 유형이죠."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "集合写真を撮りたいけど、意地のせいで誰かが言ってくれるまで待つタイプです。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "She's the sort who wants to join the group photo but waits until someone insists she join them."
L17_1.m_Talk_ENG = L18_1
L18_1 = "雖然她內心也很想拍合照，但礙於面子問題，最好是由別人開口。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "เธอเป็นประเภทอยากถ่ายรูปหมู่ แต่ก็จะเก็บทรงรอจนมีคนคะยั้นคะยอให้ไปถ่ายด้วยกัน"
L17_1.m_Talk_THA = L18_1
L18_1 = "Cô ấy là kiểu người muốn có mặt trong ảnh nhóm nhưng lại đợi cho đến khi ai đó khăng khăng mời cô ấy vào."
L17_1.m_Talk_VTN = L18_1
L18_1 = "虽然也想拍合影，但是碍于面子只能等待别人先作出提议。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Sie ist der Typ Mensch, die gerne im Gruppenfoto sein möchte, sich aber lieber von jemandem überreden lässt, weil sie zu stolz ist."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Rita est le genre de personne qui veut faire partie du groupe, mais qui ne dit rien jusqu'à ce qu'on lui propose."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "HORIZON_ACT2_INTERLUDE1@168#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 168
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 3500201
L18_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_Face = "UNIT_LAUGH"
L18_1.m_CharStrID = "DASH_HORIZON_NULL_NULL"
L18_1.m_Pos = "L"
L18_1.m_Crash = 20
L19_1 = "우와! 그럼 앞으로도 같이 사진 잔뜩 찍어요, 언니!"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "わあ！　じゃあこれからは一緒にいっぱい写真を撮りましょうね、お姉ちゃん！"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Aha! Then let's take plenty of photos together from now on, Rita!"
L18_1.m_Talk_ENG = L19_1
L19_1 = "哇喔！那我們以後一起拍很多照吧！"
L18_1.m_Talk_TWN = L19_1
L19_1 = "อ่าฮ้า! งั้นจากนี้ก็มาถ่ายรูปด้วยกันเยอะๆ เลยนะคะริตา!"
L18_1.m_Talk_THA = L19_1
L19_1 = "Aha! Vậy thì từ bây giờ chúng ta hãy chụp thật nhiều ảnh cùng nhau nhé, Rita!"
L18_1.m_Talk_VTN = L19_1
L19_1 = "呜哇！那以后我们一起拍更多照片，姐姐！"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Wow! Dann lass uns auch in Zukunft viele Fotos schießen, Rita!"
L18_1.m_Talk_DEU = L19_1
L19_1 = "Je vois ! Alors à partir de maintenant, on prendra plein de photos toutes les trois !"
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
