L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 170
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 3500201
L20_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L21_1 = "UNIT_DESPAIR"
L20_1.m_Face = L21_1
L20_1.m_CharStrID = "RITA_HORIZON_NULL_NULL"
L20_1.m_Pos = "C"
L21_1 = "……저런 엉터리 심리분석을 진심으로 믿는 너도 참 신기해."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "……あんなデタラメ心理分析を本気で信じるとは、お前も本当に不思議だな。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "…I can't believe you actually buy into that psychoanalysis garbage."
L20_1.m_Talk_ENG = L21_1
L21_1 = "……你也真是奇葩，這種毫無根據的分析你也相信。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "... เหลือจะเชื่อจริงๆ ที่เธอเชื่อจิตวิเคราะห์สายมโนแบบนั้น"
L20_1.m_Talk_THA = L21_1
L21_1 = "… Ta không thể tin rằng nhóc thực sự tin đống phế liệu đó làm phân tích tâm lý."
L20_1.m_Talk_VTN = L21_1
L21_1 = "……竟然会相信那种毫无根据的心理分析，你太容易受骗了。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Erstaunlich, dass du ihr diesen Psychoanalyse-Müll glaubst."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Comment peux-tu croire à cette psychanalyse de comptoir ?"
L20_1.m_Talk_FRA = L21_1
