L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 173
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 3500201
L23_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
