L23_1.m_Crash = 30
L24_1 = "헤헤, 그래도 이렇게 셋이 나란히 서 있으니까 꼭 한 식구 같아요."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "へへ、でもこうやって三人で並んでみたら、まるで家族みたいです。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Hehe, still, we look like a family huddled together like this."
L23_1.m_Talk_ENG = L24_1
L24_1 = "嘻嘻，我們這樣三個人站在一起，感覺好像一家人喔！"
L23_1.m_Talk_TWN = L24_1
L24_1 = "แหะแหะ เบียดๆ กันแบบนี้นี่เราเหมือนครอบครัวเลยนะคะ"
L23_1.m_Talk_THA = L24_1
L24_1 = "Hehe, không sao, chúng ta giống như một gia đình đang quây quần bên nhau như thế này."
L23_1.m_Talk_VTN = L24_1
L24_1 = "嘿嘿，不管怎么说，我们三个人站在一起，真的看起来像一家人。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Hehe, wir sind fast wie eine Familie, wenn wir zu dritt nebeneinander stehen."
L23_1.m_Talk_DEU = L24_1
L24_1 = "En tout cas, on a vraiment l'air de former une famille à poser comme ça ! Hi hi."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "HORIZON_ACT2_INTERLUDE1@174#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 174
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 3500201
L24_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_Face = "UNIT_PRIDE"
L24_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L24_1.m_Pos = "R"
L25_1 = "그렇습니다, 대시. 호라이즌 파이낸스는 1대부터 가족 같은 회사를 지향하고 있습니다."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "そうですね、ダッシュ。ホライズン・ファイナンスは1代目からアットホームな職場を目指しています。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "That's right, Dash. Horizon Finance strives to be a company like a family, ever since its foundation."
L24_1.m_Talk_ENG = L25_1
L25_1 = "沒錯，黛西。地平線金融從第一代開始，我們的理念就是要建立像家一樣的公司。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ใช่แล้วค่ะแดช ฮอไรซันไฟแนนซ์มุ่งมั่นจะเป็นบริษัทที่อยู่กันเหมือนครอบครัวมาตั้งแต่ก่อตั้ง"
L24_1.m_Talk_THA = L25_1
L25_1 = "Đúng vậy, Dash. Horizon Finance luôn phấn đấu để trở thành một công ty như một gia đình kể từ khi thành lập."
L24_1.m_Talk_VTN = L25_1
L25_1 = "是的，黛西。地平线金融最初就是想尽力打造家族氛围的公司。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "So ist es, Dash. Horizon Finance strebt seit der Gründergeneration an, eine familiäre Firma zu sein."
L24_1.m_Talk_DEU = L25_1
L25_1 = "C'est exactement ça, Dash. Depuis sa création, Horizon Finance aspire à fonctionner comme une vraie famille."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
