L31_1 = "HORIZON_ACT2_INTERLUDE1@180#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 180
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 3500201
L30_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "DASH_HORIZON_NULL_NULL"
L31_1 = "우와, 이러고 보니까 저랑 대표님이랑 진짜 언니 동생 같아요."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "うわぁ、こう見ると私と代表って本物の姉妹みたいです。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Wow, we really do look like sisters here, boss."
L30_1.m_Talk_ENG = L31_1
L31_1 = "哇喔，這麼一看，我和BOSS真的好像姊妹喔。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "โห เราดูเหมือนพี่น้องกันเลยค่ะบอส"
L30_1.m_Talk_THA = L31_1
L31_1 = "Wow, trong ảnh nhìn chúng ta thực sự trông giống như chị em, bà chủ ạ."
L30_1.m_Talk_VTN = L31_1
L31_1 = "哇，这样一来我和BOSS看起来像真的姐姐和妹妹一样。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Wow, weißt du was? Du und ich sehen wirklich aus wie Schwestern."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Wouah ! On dirait vraiment trois sœurs. Pas vrai, boss ? Avec la petite au milieu..."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "HORIZON_ACT2_INTERLUDE1@181#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 181
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 3500201
L31_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L32_1 = "……햄스워스에게 외형도 업그레이드할 수 없을지 문의하겠습니다."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "……ヘムズワースに外見もアップグレードできないか問い合わせてみます。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "…I'll ask Helmsworth if I can upgrade my exterior appearance as well."
L31_1.m_Talk_ENG = L32_1
L32_1 = "……我再問一下海姆斯沃思外型可以改造一下嗎。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "... ฉันจะลองถามเฮล์มสเวิร์ธดูนะคะว่าฉันอัปเกรดรูปลักษณ์ภายนอกด้วยได้มั้ย"
L31_1.m_Talk_THA = L32_1
L32_1 = "… Tôi sẽ hỏi Helmsworth xem liệu tôi cũng có thể nâng cấp ngoại hình của mình không."
L31_1.m_Talk_VTN = L32_1
L32_1 = "……我会咨询海姆斯沃思能不能升级外形。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Ich werde Helmsworth fragen, ob man auch mein Äußeres upgraden kann."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Il faut vraiment que je dise à Helmsworth de faire quelque chose à propos de mon apparence externe..."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "HORIZON_ACT2_INTERLUDE1@182#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 182
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 3500201
L32_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "DASH_HORIZON_NULL_NULL"
L33_1 = "앗, 잠시만요! 언니만 혼자 다른 데 보고 있어요!"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "あっ、待ってください！　お姉ちゃんだけ目線が外れています！"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Oh, wait! Rita's looking off into the distance by herself!"
L32_1.m_Talk_ENG = L33_1
L33_1 = "等一下！ 姊姊眼睛沒有看鏡頭！"
L32_1.m_Talk_TWN = L33_1
L33_1 = "โอ๊ะ เดี๋ยวนะคะ! ริตาไปยืนซะห่างเลยค่ะ!"
L32_1.m_Talk_THA = L33_1
L33_1 = "Ồ, chờ đã! Rita đang nhìn ra xa một mình!"
L32_1.m_Talk_VTN = L33_1
L33_1 = "啊，等一下！为什么只有姐姐在看别处！"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Huch, warte! Du bist die einzige, die woanders hinschaut!"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Hé, attendez ! Où est-ce que tu regardes comme ça toute seule, Rita ?"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "HORIZON_ACT2_INTERLUDE1@183#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 183
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 3500201
L33_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L34_1 = "진공관 맙소사. 다시 찍어야겠군요."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "オーマイ、真空管。撮り直しですね。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Oh my diodes. We'll have to take it again, then."
L33_1.m_Talk_ENG = L34_1
L34_1 = "我的真空管，只好重拍囉。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "โอ้ ไดโอดจะช็อต ต้องถ่ายอีกรูปแล้วสินะคะงั้น"
L33_1.m_Talk_THA = L34_1
L34_1 = "Ôi điốt của tôi. Vậy thì chúng ta sẽ phải chụp lại lần nữa."
L33_1.m_Talk_VTN = L34_1
L34_1 = "真空管在上，看来得重新拍一张了。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Oh, meine Dioden. Wir müssen das Foto noch einmal schießen."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Je n'en crois pas mes diodes. Pas le choix, prenons une autre photo."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "HORIZON_ACT2_INTERLUDE1@184#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 184
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 3500201
L34_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L35_1 = "대시에게 상사로서 모범을 보이고 싶다면 분발해 주십시오, 리타."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "ダッシュに上司として模範を示したければ頑張ってください、リタ。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "You really must try harder if you wish to lead Dash by example, Rita."
L34_1.m_Talk_ENG = L35_1
L35_1 = "麗塔，身為黛西的上司，請拿出應有的示範，加油。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ถ้าอยากเป็นตัวอย่างที่ดีให้แดชก็ต้องพยายามกว่านี้นะคะริตา"
L34_1.m_Talk_THA = L35_1
L35_1 = "Cô thực sự phải cố gắng nhiều hơn nữa nếu cô muốn dẫn dắt Dash, Rita ạ."
L34_1.m_Talk_VTN = L35_1
L35_1 = "如果你想给黛西展现模范上司的样子，需要更加努力才行。丽塔。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Streng dich bitte an, wenn du ein Vorbild für Dash sein willst, Rita."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Il va falloir faire des efforts si vous comptez servir d'exemple à Dash un jour, Rita !"
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "HORIZON_ACT2_INTERLUDE1@185#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 185
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 3500201
L35_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "RITA_HORIZON_NULL_NULL"
L36_1 = "적당히 해. 빈 속으로 떠들기도 지쳤으니까."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "いい加減にしろ。空腹で喋るのも疲れた。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Don't push it. I'm getting too hungry for banter."
L35_1.m_Talk_ENG = L36_1
L36_1 = "可以了啦，我肚子好餓沒力氣跟你們吵。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "อย่ามาหาเรื่องน่า ฉันหิวจะไม่มีอารมณ์จะขำละนะ"
L35_1.m_Talk_THA = L36_1
L36_1 = "Đừng có ép tôi nữa. Tôi quá đói để nói đùa rồi."
L35_1.m_Talk_VTN = L36_1
L36_1 = "别再烦我了。空着肚子工作这么久，已经很累了。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Das reicht jetzt. Ich bin es leid, auf leerem Magen zu quasseln."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Attention à ce que tu dis. Quand j'ai le ventre vide, je suis rarement d'humeur à plaisanter."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "HORIZON_ACT2_INTERLUDE1@186#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 186
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 3500201
L36_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "FX_CUTSCEN_NOISE_RUSTLE_03"
L36_1.m_StartFXSoundName = L37_1
L36_1.m_CharStrID = "RITA_HORIZON_NULL_NULL"
L37_1 = "젠장……. 냉장고도 텅 비었잖아. 술까지 떨어졌어."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "くそ……冷蔵庫もすっからかんか。酒もないし。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Damn it… The fridge is completely empty. We're all out of booze too."
L36_1.m_Talk_ENG = L37_1
L37_1 = "可惡……冰箱空空如也，連酒也喝完了。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "บ้าจริง... ตู้เย็นโบ๋เบ๋เลย เหล้าก็เกลี้ยงด้วย"
L36_1.m_Talk_THA = L37_1
L37_1 = "Chết tiệt… Tủ lạnh trống trơn. Hết cả đồ uống luôn."
L36_1.m_Talk_VTN = L37_1
L37_1 = "见鬼……冰箱竟然是空的。连酒也没了。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Mist ... Der Kühlschrank ist leer. Nicht mal Alkohol haben wir noch."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Bon sang... Le frigo est vide ! On n'a même plus de bières !"
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "HORIZON_ACT2_INTERLUDE1@187#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 187
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3500201
L37_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "DASH_HORIZON_NULL_NULL"
L38_1 = "장보러 가요, 언니! 대표님도 같이!"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "お買い物に行きましょう、お姉ちゃん！　代表も一緒に！"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Then let's go grocery shopping, Rita! You too, boss!"
L37_1.m_Talk_ENG = L38_1
L38_1 = "姊姊，我們去買菜吧！BOSS也一起來！"
L37_1.m_Talk_TWN = L38_1
L38_1 = "งั้นก็ไปซื้อของกันเถอะค่ะริตา! คุณก็ไปด้วยกันนะคะบอส!"
L37_1.m_Talk_THA = L38_1
L38_1 = "Vậy chúng ta hãy đi mua sắm đồ tạp hóa nào, Rita! Cô cũng đi nữa, bà chủ!"
L37_1.m_Talk_VTN = L38_1
L38_1 = "去购物吧，姐姐！BOSS也一起！"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Gehen wir einkaufen, Rita! Vorsitzende, komm mit!"
L37_1.m_Talk_DEU = L38_1
L38_1 = "Allons faire les courses, alors ! Tu viens aussi, boss ?"
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "HORIZON_ACT2_INTERLUDE1@188#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 188
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 3500201
L38_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L39_1 = "좋은 제안입니다. 최근 블랙 네트워크에서 리퍼 인더스트리제 윤활유가 호평이더군요."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "いい提案です。最近、ブラックネットワークでリーファー・インダストリー製の潤滑油が好評のようでした。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "An outstanding proposal. The lubricant product from Reaper Industries has been getting rave reviews on the Dark Network as of late."
L38_1.m_Talk_ENG = L39_1
L39_1 = "這個建議不錯。最近在黑色網路上，收割者的潤滑油好像評價不錯。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "เป็นข้อเสนอที่ยอดเยี่ยมมากค่ะ! สารหล่อลื่นจากอุตสาหกรรมรีปเปอร์เพิ่งได้รีวิวดีมากในดาร์กเน็ตเวิร์กไม่นานนี้"
L38_1.m_Talk_THA = L39_1
L39_1 = "Một đề xuất xuất sắc. Sản phẩm chất bôi trơn từ Reaper Industries đã nhận được nhiều đánh giá tích cực trên Mạng Đen vào cuối năm nay."
L38_1.m_Talk_VTN = L39_1
L39_1 = "好主意。最近黑色网络上出售的收割者牌的润滑油比较受好评。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Ein guter Vorschlag. Neuerdings gibt es gute Rezensionen im Schattennetz über das Schmiermittel von Reaper Industries."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Bonne idée. Le lubrifiant développé par Reaper Industries fait fureur sur le dark net, en ce moment."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "HORIZON_ACT2_INTERLUDE1@189#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 189
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 3500201
L39_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L40_1 = "블랙 네트워크의 미식가, 저 호라이즌이 품평해 보겠습니다."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "ブラックネットワークの美食家、ホライズンが品評してみましょう。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "As the Dark Network's most authoritative connoisseur of lubricants, I must give it a try."
L39_1.m_Talk_ENG = L40_1
L40_1 = "就讓黑色網路的美食家 地平線，來評鑑一下吧。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ในฐานะผู้เชี่ยวชาญเรื่องสารหล่อลื่นที่เชื่อถือได้ที่สุดในดาร์กเน็ตเวิร์ก ฉันคงต้องลองหน่อยแล้วค่ะ"
L39_1.m_Talk_THA = L40_1
L40_1 = "Với tư cách là người sành sỏi nhất về chất bôi trơn của Mạng Đen, tôi phải thử mới được."
L39_1.m_Talk_VTN = L40_1
L40_1 = "作为黑色网络的美食家，地平线为你品评。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Ich, Horizon, die Feinschmeckerin des Schattennetzes, werde meine Bewertung abgeben."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Ce serait faillir à ma réputation de gastronome que de passer à côté."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "HORIZON_ACT2_INTERLUDE1@190#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 190
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 3500201
L40_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_CharStrID = "RITA_HORIZON_NULL_NULL"
L41_1 = "난민지구에 그런 게 있을지는 모르겠지만……. 별 수 없군."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "難民地区にそんなものがあるかどうかはわからないけど……仕方ないな。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "I'm not sure if we'll find anything like that in a refugee district… But I guess I've got no choice."
L40_1.m_Talk_ENG = L41_1
L41_1 = "不知道難民區有沒有這樣的東西……就這樣吧。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ฉันไม่แน่ใจนะว่าเขตผู้ลี้ภัยจะมีอะไรแบบนั้นมั้ย... แต่ฉันเลือกอะไรได้มั้ยล่ะ"
L40_1.m_Talk_THA = L41_1
L41_1 = "Chả biết chúng ta có tìm thấy bất cứ thứ gì tương tự như vậy trong Khu Tị Nạn hay không… Nhưng chắc là không còn lựa chọn nào khác."
L40_1.m_Talk_VTN = L41_1
L41_1 = "不知道难民区能不能买到那个……不过也没办法了。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Hoffentlich kriegt man das im Flüchtlingsviertel überhaupt her ... aber okay."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Ça m'étonnerait qu'on trouve ça au district des réfugiés, mais enfin... Ça ne coûte rien d'essayer."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "HORIZON_ACT2_INTERLUDE1@191#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 191
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 3500201
L41_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_CharStrID = "RITA_HORIZON_NULL_NULL"
L42_1 = "꼬맹이, 넌 뭐 먹고 싶어?"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "ガキ、お前は何が食べたいんだ？"
L41_1.m_Talk_JPN = L42_1
L42_1 = "What about you, kid? Got any cravings?"
L41_1.m_Talk_ENG = L42_1
L42_1 = "小鬼，你想吃什麼？"
L41_1.m_Talk_TWN = L42_1
L42_1 = "เธอล่ะยัยหนู?๋ อยากกินอะไรมั้ย?"
L41_1.m_Talk_THA = L42_1
L42_1 = "Còn cháu thì sao, nhóc? Có đói không?"
L41_1.m_Talk_VTN = L42_1
L42_1 = "小不点，你想吃什么？"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Kleiner Knirps, und was willst du essen?"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Et toi, Dash ? Qu'est-ce qui te ferait plaisir ?"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "HORIZON_ACT2_INTERLUDE1@192#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 192
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 3500201
L42_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_CharStrID = "DASH_HORIZON_NULL_NULL"
L43_1 = "언니가 말했던 냉동 파스타요!"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "お姉ちゃんが言ってた冷凍パスタです！"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Ooh, that frozen pasta you were talking about!"
L42_1.m_Talk_ENG = L43_1
L43_1 = "我想吃姊姊說的冷凍義大利麵！"
L42_1.m_Talk_TWN = L43_1
L43_1 = "อ๋อออ พาสต้าแช่แข็งที่คุณว่าไงคะ!"
L42_1.m_Talk_THA = L43_1
L43_1 = "Ồ, cô đang nói đến món mì ống đông lạnh sao!"
L42_1.m_Talk_VTN = L43_1
L43_1 = "我想吃姐姐之前说的冷冻意大利面！"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Die Tiefkühlpasta, von der du erzählt hast!"
L42_1.m_Talk_DEU = L43_1
L43_1 = "Moi ? Les pâtes surgelées dont tu parlais l'autre fois !"
L42_1.m_Talk_FRA = L43_1
