L48_1 = "FX_CUTSCEN_BEEP"
L47_1.m_StartFXSoundName = L48_1
L48_1 = "<color=#ffd34c>영상 기록 재생 중 치명적인 오류가 발생하였습니다.</color>"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "<color=#ffd34c>映像記録再生中に致命的なエラーが発生しました。</color>"
L47_1.m_Talk_JPN = L48_1
L48_1 = "<color=#ffd34c>A critical error occurred during video record playback.</color>"
L47_1.m_Talk_ENG = L48_1
L48_1 = "<color=#ffd34c>播放影像紀錄時發生致命錯誤。</color>"
L47_1.m_Talk_TWN = L48_1
L48_1 = "<color=#ffd34c>เกิดข้อผิดพลาดร้ายแรงขณะเล่นวิดีโอที่บันทึกไว้</color>"
L47_1.m_Talk_THA = L48_1
L48_1 = "<color=#ffd34c>Đã xảy ra lỗi nghiêm trọng khi phát lại bản ghi video.</color>"
L47_1.m_Talk_VTN = L48_1
L48_1 = "<color=#ffd34c>播放视频记录时发生严重错误。</color>"
L47_1.m_Talk_SCN = L48_1
L48_1 = "<color=#ffd34c>Während der Wiedergabe einer Videoaufzeichnung ist ein kritischer Fehler aufgetreten.</color>"
L47_1.m_Talk_DEU = L48_1
L48_1 = "<color=#ffd34c>Une erreur critique est survenue durant la lecture de la vidéo.</color>"
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "HORIZON_ACT2_INTERLUDE1@198#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 198
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 3500201
L48_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "<color=#ffd34c>사고회로의 과부하 감지. 원인을 파악 중입니다.</color>"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "<color=#ffd34c>思考回路の過負荷感知。原因を把握中です。</color>"
L48_1.m_Talk_JPN = L49_1
L49_1 = "<color=#ffd34c>Reasoning system overloaded. Running diagnostics…</color>"
L48_1.m_Talk_ENG = L49_1
L49_1 = "<color=#ffd34c>思考迴路超載，正在調查原因。</color>"
L48_1.m_Talk_TWN = L49_1
L49_1 = "<color=#ffd34c>ระบบการให้เหตุผลทำงานหนักเกินไป กำลังวินิจฉัย…</color>"
L48_1.m_Talk_THA = L49_1
L49_1 = "<color=#ffd34c>Hệ thống lập luận bị quá tải. Đang chạy chẩn đoán…</color>"
L48_1.m_Talk_VTN = L49_1
L49_1 = "<color=#ffd34c>检测到思维回路过载。正在分析原因。</color>"
L48_1.m_Talk_SCN = L49_1
L49_1 = "<color=#ffd34c>Das Denksystem ist überlastet. Diagnose wird ausgeführt.</color>"
L48_1.m_Talk_DEU = L49_1
L49_1 = "<color=#ffd34c>Surcharge du système de raisonnement. Diagnostic en cours.</color>"
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "HORIZON_ACT2_INTERLUDE1@199#Talk"
L49_1.m_CutScenKey_Talk = L50_1
