L51_1 = "FX_COMBAT_ALL_ELECTRIC_ATTACK_SMALL"
L50_1.m_StartFXSoundName = L51_1
L51_1 = "<color=#ffd34c>침식파에 노출된 상태로 기동시간이 한계에 달했습니다. 사고회로 재기동 절차를 시행합니다.</color>"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "<color=#ffd34c>侵食波にさらされた状態での起動時間が限界に達しました。思考回路の再起動手続きを行います。</color>"
L50_1.m_Talk_JPN = L51_1
L51_1 = "<color=#ffd34c>System operation timed out due to exposure to Corruption Rays. Reinitializing reasoning system.</color>"
L50_1.m_Talk_ENG = L51_1
L51_1 = "<color=#ffd34c>暴露在侵蝕波的狀態下，運作時間已達到極限。將重新啟動思考迴路。</color>"
L50_1.m_Talk_TWN = L51_1
L51_1 = "<color=#ffd34c>รอให้ระบบดำเนินการนานเกินไปเนื่องจากสัมผัสกับรังสีคอร์รัปชั่น กำลังเริ่มการทำงานของระบบการให้เหตุผลอีกครั้ง</color>"
L50_1.m_Talk_THA = L51_1
L51_1 = "<color=#ffd34c>Hoạt động của hệ thống đã hết thời gian do phơi nhiễm quá mức với Tia Ăn Mòn. Khởi động lại hệ thống lý luận.</color>"
L50_1.m_Talk_VTN = L51_1
L51_1 = "<color=#ffd34c>暴露在侵蚀波状态下，启动时间达到极限。执行思维回路重新启动程序。</color>"
L50_1.m_Talk_SCN = L51_1
L51_1 = "<color=#ffd34c>Die Manövrierzeit hat aufgrund der Belastung durch Verderbniswellen ihre Grenze erreicht. Prozeduren für eine Neuinitialisierung des Denksystems werden ausgeführt.</color>"
L50_1.m_Talk_DEU = L51_1
L51_1 = "<color=#ffd34c>Le délai d'opération a expiré en raison de l'exposition aux Rayons de Corruption. Réinitialisation du système de raisonnement.</color>"
L50_1.m_Talk_FRA = L51_1
