L9_1 = "FX_CUTSCEN_BEEP"
L8_1.m_StartFXSoundName = L9_1
L9_1 = "<color=#ffd34c>경고. 외부에서의 물리적인 접촉 감지. 재생을 중단합니다.</color>"
L8_1.m_Talk_KOREA = L9_1
