L11_1 = "HORIZON_ACT2_INTERLUDE1@210#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 210
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 3500201
L10_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "RACHEL_NPC_NULL_NULL"
L10_1.m_CharStrID = L11_1
L10_1.m_Pos = "C"
L10_1.m_Crash = 15
L11_1 = "아, 미, 미안. 방해하려는 생각은 없었어."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "あ、ご、ごめん。邪魔するつもりはなかったんだ。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Oh, sorry. I didn't mean to interrupt."
L10_1.m_Talk_ENG = L11_1
L11_1 = "抱…抱歉，我不是故意要打擾你。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "โอ๊ะ ขอโทษที ไม่ได้ตั้งใจจะขัดนะ"
L10_1.m_Talk_THA = L11_1
L11_1 = "Ồ xin lỗi. Chị không cố ý làm gián đoạn."
L10_1.m_Talk_VTN = L11_1
L11_1 = "啊，对不起。我没想打扰你。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Oh, s-sorry. Ich wollte nicht stören."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Oh, pardon. Je voulais pas te déranger."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "HORIZON_ACT2_INTERLUDE1@211#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 211
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 3500201
L11_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "RACHEL_NPC_NULL_NULL"
L11_1.m_CharStrID = L12_1
L11_1.m_Pos = "C"
L12_1 = "그냥 네가 아무리 불러도 이거만 빤히 보고 있길래."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "何度も呼んだのに、こればかりじっと見ていたからさ。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "It's just that you wouldn't stop staring at this no matter how many times I called you."
L11_1.m_Talk_ENG = L12_1
L12_1 = "但我一直叫你你都不理，只是一直盯着這個看。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "แต่แบบ ฉันเรียกเท่าไหร่เธอก็เอาแต่จ้องไอ้นี่ไง"
L11_1.m_Talk_THA = L12_1
L12_1 = "Chỉ là em cứ không ngừng nhìn chằm chằm vào bức ảnh này cho dù chị đã gọi em bao nhiêu lần."
L11_1.m_Talk_VTN = L12_1
L12_1 = "只是因为无论怎么叫你，你都只盯着这个看。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Du hast bloß unentwegt draufgestarrt, obwohl ich dich gerufen habe."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Je t'ai appelée plusieurs fois, mais tu répondais pas. T'étais trop absorbée par ce truc, là..."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "HORIZON_ACT2_INTERLUDE1@212#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 212
