L12_1.m_Face = "UNIT_HATE"
L12_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L12_1.m_Pos = "C"
L13_1 = "그 액자는 내려 두십시오. 휴먼. 사생활 침해로 고소하겠습니다."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "その写真立ては放っておいてください、ヒューマン。プライバシー侵害で告訴します。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Put down that picture, human. Or I will sue you for invasion of privacy."
L12_1.m_Talk_ENG = L13_1
L13_1 = "人類，請放下那個相框，否則我會告你侵犯隱私。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "วางรูปนั่นลงซะค่ะมนุษย์ ไม่งั้นจะฟ้องข้อหาล่วงล้ำความเป็นส่วนตัวนะคะ"
L12_1.m_Talk_THA = L13_1
L13_1 = "Bỏ bức ảnh đó xuống, con người. Nếu không tôi sẽ kiện cô vì tội xâm phạm quyền riêng tư."
L12_1.m_Talk_VTN = L13_1
L13_1 = "把那个相框放下。人类。不然我会以侵犯私生活的罪名起诉你。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Leg den Fotorahmen ab, Mensch. Sonst zeige ich dich wegen Verletzung der Privatsphäre an."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Posez ce cadre immédiatement ou je vous fais un procès pour atteinte à la vie privée, humaine."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "HORIZON_ACT2_INTERLUDE1@213#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 213
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 3500201
L13_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_Face = "UNIT_SURPRISE"
L14_1 = "RACHEL_NPC_NULL_NULL"
L13_1.m_CharStrID = L14_1
L13_1.m_Pos = "C"
L13_1.m_Crash = 20
L14_1 = "알았어! 내려 두면 되잖아, 내려 두면!"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "わかったよ！　置いておけばいいんでしょ！"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Sheesh, fine! I'll put it down, okay?"
L13_1.m_Talk_ENG = L14_1
L14_1 = "好嘛，我放下就是了，放就放！"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ฮู้ยยยย จร้า! วางจร้า โอเค?"
L13_1.m_Talk_THA = L14_1
L14_1 = "Xì, tốt thôi! Chị sẽ đặt nó xuống, được chưa?"
L13_1.m_Talk_VTN = L14_1
L14_1 = "知道了！我这就放下！放下不就行了吗！"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Meine Güte, ist ja gut! Ich lege es hin, okay?"
L13_1.m_Talk_DEU = L14_1
L14_1 = "Ok, ok ! Je le pose ! Voilà, contente ?"
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "HORIZON_ACT2_INTERLUDE1@214#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 214
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 3500201
L14_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L15_1 = "UNIT_DESPAIR"
L14_1.m_Face = L15_1
L15_1 = "RACHEL_NPC_NULL_NULL"
L14_1.m_CharStrID = L15_1
L14_1.m_Pos = "C"
L15_1 = "그런데 이 사람들, 누구야? 혹시 헤어진 가족들?"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "ていうかこの人たちは誰？　家族なの？"
L14_1.m_Talk_JPN = L15_1
L15_1 = "By the way, who are these people? Are they… family? Before you got separated?"
L14_1.m_Talk_ENG = L15_1
L15_1 = "不過這些人是誰？是你分開的家人嗎？"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ว่าแต่คนพวกนี้ใครน่ะ? ครอบครัวเหรอ? ก่อนถูกจับแยกมาเหรอ?"
L14_1.m_Talk_THA = L15_1
L15_1 = "Nhân tiện, những người này là ai? Họ là… gia đình của em? Trước khi em bị chia cắt ư?"
L14_1.m_Talk_VTN = L15_1
L15_1 = "不过这些人是谁？是你失散的家人吗？"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Übrigens, wer sind diese Leute? Sind sie etwa deine Familie, die du verloren hast?"
L14_1.m_Talk_DEU = L15_1
L15_1 = "Mais au fait, qui sont ces gens ? La famille dont tu as été séparée ?"
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
