L17_1 = "HORIZON_ACT2_INTERLUDE1@216#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 216
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 3500201
L16_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L16_1.m_Pos = "C"
L17_1 = "같은 조립공정에서 태어나지는 않았지만, 비슷합니다."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "同じ組立工程で生まれてはいませんが、似たようなものです。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "We were not manufactured from the same facility, but yes, something like family."
L16_1.m_Talk_ENG = L17_1
L17_1 = "雖然不是從同一個組裝製程產出的，卻很相似。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "เราไม่ได้ถูกผลิตมาจากที่เดียวกัน แต่ก็ใช่ค่ะ ก็ทำนองว่าครอบครัว"
L16_1.m_Talk_THA = L17_1
L17_1 = "Chúng tôi không được sản xuất từ cùng một cơ sở, nhưng đúng, chúng tôi giống như một gia đình."
L16_1.m_Talk_VTN = L17_1
L17_1 = "虽然不是同一个生产线出生的，但差不多吧。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Wir wurden nicht aus der gleichen Fabrik hergestellt, aber ja, so etwas wie eine Familie."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Nous n'avons pas été assemblées dans la même usine, mais je suppose qu'on peut dire ça."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
