L20_1 = "HORIZON_ACT2_INTERLUDE1@219#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 219
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 3500201
L19_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L19_1.m_Pos = "L"
L20_1 = "오늘은 무슨 일입니까. 당신이 제공한 보육원에서의 1박은 소화했습니다만."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "今日は何の用ですか？　あなたが提供した孤児院での1泊は消化したはずですが。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "What business brings you here today? I've already spent the night at the orphanage as you insisted."
L19_1.m_Talk_ENG = L20_1
L20_1 = "今天來找我有什麼事嗎？你提供的來去育幼院住一晚，行程我已經走完了。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ว่าแต่มีธุระอะไรเหรอคะวันนี้? ฉันค้างที่บ้านเด็กกำพร้าคืนหนึ่งตามที่คุณคะยั้นคะยอแล้วนี่คะ"
L19_1.m_Talk_THA = L20_1
L20_1 = "Có chuyện gì khiến cô đến đây hôm nay? Tôi đã qua đêm ở trại trẻ mồ côi như cô đã nài nỉ."
L19_1.m_Talk_VTN = L20_1
L20_1 = "今天有什么事。我已经在你的孤儿院留宿了一天。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Welches Geschäft führt dich heute hierher? Ich habe die Nacht bereits im Waisenhaus verbracht, weil du darauf bestanden hast."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Que faites-vous ici ? J'ai pourtant passé la nuit à l'orphelinat comme vous le vouliez."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "HORIZON_ACT2_INTERLUDE1@220#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 220
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 3500201
L20_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L20_1.m_Pos = "L"
L21_1 = "여담으로 점수를 드리자면 별점 5점 만점 중 1점 드리겠습니다."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "余談ですが点数をつけるなら、星5点満点中1点でした。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "On a side note, if I had to give it a score, I'd give it one star out of five."
L20_1.m_Talk_ENG = L21_1
L21_1 = "要給分的話，滿分5分，我給1分。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "แล้วก็บอกเผื่อไว้นะคะ ถ้าต้องให้คะแนน ฉันให้หนึ่งเต็มห้าค่ะ"
L20_1.m_Talk_THA = L21_1
L21_1 = "Một lưu ý nhỏ, nếu tôi phải chấm điểm, tôi sẽ cho nó một trên năm sao."
L20_1.m_Talk_VTN = L21_1
L21_1 = "另外让我评分的话，如果5分满分，我只能给1分。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Nebenbei bemerkt, würde ich einen von fünf Sternen geben, wenn ich es bewerten müsste."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Entre parenthèses cette soirée ne valait pas plus qu'un 1 sur 5, si vous voulez mon avis."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "HORIZON_ACT2_INTERLUDE1@221#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 221
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 3500201
L21_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_Face = "UNIT_HATE"
L22_1 = "RACHEL_NPC_NULL_NULL"
L21_1.m_CharStrID = L22_1
L21_1.m_Pos = "R"
L21_1.m_Crash = 10
L22_1 = "엥? 왜? 식단도 좋았고 침대도 매트리스 멀쩡한 걸로 쓰게 해 줬는데?"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "え？　なんでよ？　ご飯も美味しかったし、ベッドもまともなマットレスを使わせてあげたのに。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Huh? Why? Supper was tasty and I made sure you got the good bed!"
L21_1.m_Talk_ENG = L22_1
L22_1 = "蛤？為什麼？菜色也很好，我還把正常的床墊給你用欸？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "หา? ไหงงั้นล่ะ? อาหารเย็นก็ดีแถมฉันหาเตียงดีๆ ให้นอนอีกนะ!"
L21_1.m_Talk_THA = L22_1
L22_1 = "Huh? Tại sao? Bữa tối thật ngon và chị đảm bảo rằng em đã có được một chiếc giường êm mà!"
L21_1.m_Talk_VTN = L22_1
L22_1 = "呃？为什么？食物明明很好吃，我还让你用了最好的床垫啊？"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Häh? Wieso denn? Das Abendessen war lecker und ich habe dafür gesorgt, dass du ein Bett mit einer intakten Matratze bekommst!"
L21_1.m_Talk_DEU = L22_1
L22_1 = "Hein ? Mais pourquoi ? Le dîner était délicieux et je t'ai même préparé le lit avec le meilleur matelas !"
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "HORIZON_ACT2_INTERLUDE1@222#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 222
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 3500201
L22_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_Face = "UNIT_IDLE"
L22_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L22_1.m_Pos = "L"
L23_1 = "다른 휴먼들이 저를 어떤 시선으로 보는지는 쉽게 인지할 수 있습니다."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "他のヒューマンが私をどんな目で見ているのかは簡単に認知できます。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "I could easily detect the way the other humans viewed me."
L22_1.m_Talk_ENG = L23_1
L23_1 = "很容易可以察覺，其他人是怎麼看我的。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ฉันตรวจจับได้ไวค่ะว่ามนุษย์คนอื่นๆ มองฉันยังไง"
L22_1.m_Talk_THA = L23_1
L23_1 = "Tôi có thể dễ dàng phát hiện ra cách những người khác nhìn tôi."
L22_1.m_Talk_VTN = L23_1
L23_1 = "我能轻易看出其他人类是以何种眼光看我的。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Ich kann mit Leichtigkeit erkennen, mit welchen Gedanken die Menschen mich ansehen."
L22_1.m_Talk_DEU = L23_1
L23_1 = "À cause de la façon dont les autres humains présents me regardaient."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "HORIZON_ACT2_INTERLUDE1@223#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 223
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 3500201
L23_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L23_1.m_Pos = "L"
L24_1 = "그들에게 전 성능 문제로 환불된 재고품이겠죠."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "彼らにとって私は性能の問題で返品された在庫品でしょう。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "To them, I'm nothing but a flawed, returned product."
L23_1.m_Talk_ENG = L24_1
L24_1 = "對他們來說，我應該就是因為性能不佳而遭退貨的庫存吧？"
L23_1.m_Talk_TWN = L24_1
L24_1 = "สำหรับพวกเขาแล้ว ฉันเป็นแค่ผลิตภัณฑ์บกพร่องที่ถูกส่งคืน"
L23_1.m_Talk_THA = L24_1
L24_1 = "Đối với họ, tôi chẳng là gì ngoài một sản phẩm khiếm khuyết bị trả lại."
L23_1.m_Talk_VTN = L24_1
L24_1 = "对他们来说，我可能是因为性能问题被退货的库存产品吧。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Für sie bin ich nichts als ein fehlerhaftes, storniertes Produkt."
L23_1.m_Talk_DEU = L24_1
L24_1 = "À leurs yeux, je n'étais manifestement rien de plus qu'un produit défectueux."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = 224
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 3500201
L24_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L24_1.m_bWaitClick = false
L24_1.m_fWaitTime = 0
