L26_1 = "HORIZON_ACT2_INTERLUDE1@225#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 225
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 3500201
L25_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_Face = "UNIT_IDLE"
L25_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L25_1.m_Pos = "C"
L26_1 = "그러니 다시 묻겠습니다. 오늘은 무슨 일입니까."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "ですので、もう一度尋ねます。今日は何の用ですか。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "So let me ask again. What business brings you here today?"
L25_1.m_Talk_ENG = L26_1
L26_1 = "所以我再問一次，今天來找我有什麼事嗎？"
L25_1.m_Talk_TWN = L26_1
L26_1 = "งั้นขอฉันถามอีกครั้งนะคะ ที่วันนี้มานี่มีธุระอะไรคะ?"
L25_1.m_Talk_THA = L26_1
L26_1 = "Vậy để tôi hỏi lại. Điều gì khiến cô đến đây hôm nay?"
L25_1.m_Talk_VTN = L26_1
L26_1 = "所以我再问你一次。今天找我什么事？"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Also lass mich nochmal fragen. Welches Geschäft führt dich heute hierher?"
L25_1.m_Talk_DEU = L26_1
L26_1 = "Je réitère ma question. Que faites-vous ici ?"
L25_1.m_Talk_FRA = L26_1
