L30_1 = "……생체 정보 확인 완료. 강민우. 자경단 자문역."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "……生体情報確認完了。マツダ・シュウイチ、自警団の諮問役。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "…Biometrics identified. Kang Minwoo. An adviser to the neighborhood watch."
L29_1.m_Talk_ENG = L30_1
L30_1 = "……生物資訊確認完畢。姜民宇，自衛隊顧問。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "... ยืนยันข้อมูลชีวมาตรแล้ว คัง มินวู ผู้ให้คำปรึกษายามเฝ้าระวัง"
L29_1.m_Talk_THA = L30_1
L30_1 = "… Sinh trắc học được xác định. Kang Minwoo. Một cố vấn cho cảnh vệ khu phố."
L29_1.m_Talk_VTN = L30_1
L30_1 = "……已确认生物信息。姜民宇，自卫队的顾问。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Biometrische Daten identifiziert. Kang Minwoo. Ein Berater der Stadtwache."
L29_1.m_Talk_DEU = L30_1
L30_1 = "... Analyse biométrique terminée. Kang Minwoo. Consultant des Sentinelles."
L29_1.m_Talk_FRA = L30_1
