L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "R"
L34_1 = "바쁜 와중에 찾아온 입장이니 바로 본론으로 들어가지."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "忙しいのに急に訪ねて悪いな、さっそく本題に入ろう。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "I'll cut right to the chase, since you seem busy."
L33_1.m_Talk_ENG = L34_1
L34_1 = "百忙之中打擾，那我就直接進入正題吧！"
L33_1.m_Talk_TWN = L34_1
L34_1 = "เธอดูยุ่งๆ ฉันเข้าเรื่องเลยแล้วกันนะ"
L33_1.m_Talk_THA = L34_1
L34_1 = "Anh sẽ nói thẳng, vì nhóc có vẻ bận."
L33_1.m_Talk_VTN = L34_1
L34_1 = "时间不多了，那就直接进入正题吧。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Ich komme gleich zur Sache, da du beschäftigt zu sein scheinst."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Tu as l'air occupée, alors je vais aller droit au but."
L33_1.m_Talk_FRA = L34_1
