L35_1 = "SEONGTAE_MILITIA_NULL_NULL"
L34_1.m_CharStrID = L35_1
L34_1.m_Pos = "R"
L35_1 = "자경단 사람들을 도와 줄 생각 없나?"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "自警団に手を貸してくれないか？"
L34_1.m_Talk_JPN = L35_1
L35_1 = "How would you like to help out the neighborhood watch?"
L34_1.m_Talk_ENG = L35_1
L35_1 = "你願意來幫忙自衛隊嗎？"
L34_1.m_Talk_TWN = L35_1
L35_1 = "เธออยากช่วยงานยามเฝ้าระวังบ้างมั้ย?"
L34_1.m_Talk_THA = L35_1
L35_1 = "Nhóc nghĩ sao về việc giúp đỡ cảnh vệ khu phố?"
L34_1.m_Talk_VTN = L35_1
L35_1 = "你有兴趣帮助自卫队的人吗？"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Würdest du der Stadtwache helfen?"
L34_1.m_Talk_DEU = L35_1
L35_1 = "Que dirais-tu d'aider les Sentinelles dans leurs opérations ?"
L34_1.m_Talk_FRA = L35_1
