L37_1 = "HORIZON_ACT2_INTERLUDE1@236#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 236
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 3500201
L36_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "SEONGTAE_MILITIA_NULL_NULL"
L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "R"
L37_1 = "이유는 들을 수 있겠지."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "理由ぐらいは聞かせてくれるよな。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Can you at least tell me why?"
L36_1.m_Talk_ENG = L37_1
L37_1 = "可以知道理由吧？"
L36_1.m_Talk_TWN = L37_1
L37_1 = "บอกหน่อยได้มั้ยว่าทำไม?"
L36_1.m_Talk_THA = L37_1
L37_1 = "Ít nhất nhóc có thể cho anh biết tại sao không?"
L36_1.m_Talk_VTN = L37_1
L37_1 = "我想听听理由。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Kannst du mir wenigstens sagen, warum?"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Tu peux au moins me dire pourquoi ?"
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "HORIZON_ACT2_INTERLUDE1@237#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 237
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3500201
L37_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L37_1.m_Pos = "L"
L38_1 = "이 프레임의 동력은 다른 기체에 비해 충전하기 매우 까다로운 편입니다."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "このフレームの動力エネルギーは、他の機体に比べて充電するのが非常に難しいです。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Compared to the other models, this frame is extremely tricky to charge."
L37_1.m_Talk_ENG = L38_1
L38_1 = "比起其他機器，這副軀殼的充電方式非常麻煩。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "เทียบกับรุ่นอื่นๆ แล้ว เฟรมนี้ชาร์จยากสุดๆ ค่ะ"
L37_1.m_Talk_THA = L38_1
L38_1 = "So với các model khác, khung này cực kỳ khó sạc."
L37_1.m_Talk_VTN = L38_1
L38_1 = "这个躯壳的动力相比其他机体来说很难进行充能。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Im Vergleich zu den anderen Modellen ist dieser Rahmen extrem schwierig zu laden."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Contrairement aux autres modèles, mon armature actuelle est particulièrement difficile à recharger."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "HORIZON_ACT2_INTERLUDE1@238#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 238
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 3500201
L38_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L38_1.m_Pos = "L"
L39_1 = "따라서 제 잔여 동력을 불필요한 곳에 낭비하는 것은 경제 원리에 어긋납니다."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "したがって、私の残余エネルギーを余計なところに費やすことは、経済原理に反します。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Therefore, it is simply not economical to waste what remains of my power on non-essential activities."
L38_1.m_Talk_ENG = L39_1
L39_1 = "因此，將我剩餘的動能浪費在不必要的事上，是違反經濟效率的。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "ดังนั้น ถ้าเอาพลังงานที่เหลืออยู่ของฉันไปใช้ในกิจกรรมที่ไม่จำเป็น มันก็จะเป็นการไม่ประหยัดค่ะ"
L38_1.m_Talk_THA = L39_1
L39_1 = "Vì vậy, sẽ không kinh tế nếu lãng phí nguồn năng lượng còn lại của tôi vào các hoạt động không thiết yếu."
L38_1.m_Talk_VTN = L39_1
L39_1 = "将剩余动力浪费在不必要的地方不符合经济原理。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Daher ist es nicht wirtschaftlich, meine verbleibende Kraft für nicht wesentliche Aktivitäten zu verschwenden."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Et au vu du niveau d'énergie qu'il me reste, je préfère l'employer pour des activités essentielles exclusivement."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
