L41_1 = "RACHEL_NPC_NULL_NULL"
L40_1.m_CharStrID = L41_1
L40_1.m_Pos = "C"
L41_1 = "평범하게 얘기하면 귀찮다는 뜻이잖아."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "簡単に言うと、めんどいってことじゃない？"
L40_1.m_Talk_JPN = L41_1
L41_1 = "So basically you can't be bothered."
L40_1.m_Talk_ENG = L41_1
L41_1 = "說直白一點，就是嫌麻煩不是嗎？！"
L40_1.m_Talk_TWN = L41_1
L41_1 = "พูดง่ายๆ ก็คืออย่ามารบกวนเธองี้"
L40_1.m_Talk_THA = L41_1
L41_1 = "Vì vậy, về cơ bản là em không thích bị làm phiền."
L40_1.m_Talk_VTN = L41_1
L41_1 = "那可以理解为懒得帮忙吧。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Das heißt doch normal ausgedrückt nur, dass du keine Lust hast."
L40_1.m_Talk_DEU = L41_1
L41_1 = "En gros, tu as la flemme ?"
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "HORIZON_ACT2_INTERLUDE1@241#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 241
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 3500201
L41_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L41_1.m_Pos = "C"
L42_1 = "명쾌한 해석 감사합니다, 휴먼."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "明快な解釈助かります、ヒューマン。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "I appreciate the clarification, human."
L41_1.m_Talk_ENG = L42_1
L42_1 = "謝謝你直白的說明，人類。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ขอบคุณที่ช่วยแถลงไขนะคะมนุษย์"
L41_1.m_Talk_THA = L42_1
L42_1 = "Tôi đánh giá cao khả năng hiểu của cô, con người ạ."
L41_1.m_Talk_VTN = L42_1
L42_1 = "你的解释很清楚，谢谢你。人类。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Danke für die klasse Übersetzung, Mensch."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Merci pour cet éclaircissement, humaine."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "HORIZON_ACT2_INTERLUDE1@242#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 242
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 3500201
L42_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_Face = "UNIT_HATE"
L43_1 = "RACHEL_NPC_NULL_NULL"
L42_1.m_CharStrID = L43_1
L42_1.m_Pos = "C"
L42_1.m_Crash = 15
L43_1 = "감사하지 말고……."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "いや、感謝されても……"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Don't thank me just yet…"
L42_1.m_Talk_ENG = L43_1
L43_1 = "謝什麼謝……"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ไม่ต้องรีบขอบคุณก็ได้..."
L42_1.m_Talk_THA = L43_1
L43_1 = "Đừng cảm ơn chị vội..."
L42_1.m_Talk_VTN = L43_1
L43_1 = "不用谢我……"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Spar dir deinen Dank ..."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Ne me remercie pas pour ça..."
L42_1.m_Talk_FRA = L43_1
