L46_1 = "HORIZON_ACT2_INTERLUDE1@245#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 245
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 3500201
L45_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_Face = "UNIT_LAUGH"
L46_1 = "SEONGTAE_MILITIA_NULL_NULL"
L45_1.m_CharStrID = L46_1
L45_1.m_Pos = "L"
L46_1 = "너무 걱정 마라. 힘쓰는 일을 시키려고 할 생각은 없어."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "それは心配するな。力仕事をさせるつもりはない。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Don't worry. They're not going to make you do anything exhausting."
L45_1.m_Talk_ENG = L46_1
L46_1 = "別擔心，我不是想讓你做些耗費力氣的事。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ไม่ต้องห่วงนะ พวกเขาไม่ให้เธอทำอะไรจนหมดแรงหรอก"
L45_1.m_Talk_THA = L46_1
L46_1 = "Đừng lo lắng. Họ sẽ không khiến nhóc làm bất cứ điều gì mệt mỏi."
L45_1.m_Talk_VTN = L46_1
L46_1 = "别担心。不会让你干很累的工作。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Mach dir keine Sorgen. Sie werden dich nicht beauftragen, Anstrengendes zu tun."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Ne t'inquiète pas pour ça, Horizon. Ce ne sera rien de fatiguant."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "HORIZON_ACT2_INTERLUDE1@246#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 246
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 3500201
L46_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "SEONGTAE_MILITIA_NULL_NULL"
L46_1.m_CharStrID = L47_1
L46_1.m_Pos = "L"
L47_1 = "자경단원들도 요즘 네가 눈에 밟히나 보더군. 아무래도 레이첼과 자주 어울려 다니니까."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "自警団員たちも最近、あんたのことが気になるみたいでね。なぜなら、レイチェルと仲良くしているからな。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "You seem to have caught their eye recently. I mean, you do hang out with Rachel a lot these days."
L46_1.m_Talk_ENG = L47_1
L47_1 = "最近你跟瑞秋常混在一起，感情很好的樣子，所以自衛隊的人也有發現到你這個人。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "พอดีช่วงนี้เธอออกจะเป็นที่สนใจของพวกเขาน่ะ เพราะเดี๋ยวนี้อยู่กับเรเชลบ่อย"
L46_1.m_Talk_THA = L47_1
L47_1 = "Gần đây nhóc có vẻ đã lọt vào mắt xanh của họ. Ý anh là, gần đây nhóc thường đi cùng Rachel."
L46_1.m_Talk_VTN = L47_1
L47_1 = "自卫队的人可能最近也在注意你。毕竟你和雷切尔经常一起出入。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Du scheinst ihnen kürzlich aufgefallen zu sein. Denn du verbringst neuerdings viel Zeit mit Rachel."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Tu as attiré l'attention des Sentinelles récemment. Il faut dire qu'à force de traîner avec Rachel en permanence..."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "HORIZON_ACT2_INTERLUDE1@247#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 247
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 3500201
L47_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "SEONGTAE_MILITIA_NULL_NULL"
L47_1.m_CharStrID = L48_1
L47_1.m_Pos = "L"
L48_1 = "자질구레한 일처리를 돕는 대신 용돈을 받는다고 생각해."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "細かい仕事を手伝う代わりに、小遣いをもらえると思ってくれ。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Think of it as running a few errands for some spending money."
L47_1.m_Talk_ENG = L48_1
L48_1 = "你就不要當作是來做事的，而是來賺零用錢的。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "คิดซะว่าไปทำธุระเล็กน้อยแลกเงินใช้"
L47_1.m_Talk_THA = L48_1
L48_1 = "Hãy nghĩ về nó như là chạy một vài công việc vặt để có chút tiền tiêu."
L47_1.m_Talk_VTN = L48_1
L48_1 = "你可以认为是通过帮一些小忙来赚零花钱。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Betrachte es als ein paar Besorgungen für etwas Taschengeld."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Tout ce qu'on te demande, c'est de nous rendre un petit service. Rémunéré, bien entendu."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "HORIZON_ACT2_INTERLUDE1@248#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 248
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 3500201
L48_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "RACHEL_NPC_NULL_NULL"
L48_1.m_CharStrID = L49_1
L48_1.m_Pos = "R"
L49_1 = "그래. 네가 정 그렇게 혼자 살고 싶으면 돈은 스스로 벌어야지."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "そうだよ。本気で一人暮らしをしたければ、お金は自分で稼がないと。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "He's right, you know. You should earn your keep if you really want to live by yourself."
L48_1.m_Talk_ENG = L49_1
L49_1 = "對啊，你想獨立生活，就需要賺錢養活自己吧。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ถูกของเขานะ ถ้าอยากอยู่คนเดียวก็ต้องทำมาหากินสิ"
L48_1.m_Talk_THA = L49_1
L49_1 = "Nhóc biết đấy, anh ấy nói đúng. Nhóc nên kiếm tiền nếu thực sự muốn sống một mình."
L48_1.m_Talk_VTN = L49_1
L49_1 = "是啊。如果你想独自生活的话，需要自己赚钱。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Er hat Recht. Du solltest dir deinen Lebensunterhalt verdienen, wenn du so gerne alleine leben würdest."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Oui, voilà. Si tu veux voler de tes propres ailes il faut bien que tu gagnes ta vie, non ?"
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "HORIZON_ACT2_INTERLUDE1@249#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 249
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 3500201
L49_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L49_1.m_Face = "UNIT_PRIDE"
L50_1 = "RACHEL_NPC_NULL_NULL"
L49_1.m_CharStrID = L50_1
L49_1.m_Pos = "R"
L50_1 = "일하면서 자경단 사람들이랑도 좀 친해지고 말이야."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "仕事しながら自警団の人とも仲良くなれるしね。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Plus, you could get to know the neighborhood watch folks a little better."
L49_1.m_Talk_ENG = L50_1
L50_1 = "在那邊工作，也可以和自衛隊的人更親近一點。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "แถมเธอยังควรไปรู้จักพวกยามเฝ้าระวังให้ดีกว่านี้อีกนิดนะ"
L49_1.m_Talk_THA = L50_1
L50_1 = "Thêm vào đó, em có thể biết rõ hơn một chút về cảnh vệ khu phố."
L49_1.m_Talk_VTN = L50_1
L50_1 = "也能通过工作交到自卫队的朋友。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Außerdem könntest du die Leute von der Stadtwache besser kennenlernen."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Et puis ce sera l'occasion de te rapprocher un peu des gars des Sentinelles !"
L49_1.m_Talk_FRA = L50_1
