L2_1 = "HORIZON_ACT2_INTERLUDE1@251#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 251
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 3500201
L1_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L1_1.m_Face = "UNIT_IDLE"
L1_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L1_1.m_Pos = "C"
L2_1 = "관계 개선은 필요없습니다. 저는 휴먼들이 싫으니까요."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "関係の改善は必要ありません。私はヒューマンが嫌いですから。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "I have no need for improving relations with the community. I do not like humans."
L1_1.m_Talk_ENG = L2_1
L2_1 = "我不喜歡人類，所以不需要改善關係。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ฉันไม่จำเป็นต้องพัฒนาความสัมพันธ์กับชุมชนนะคะ ฉันไม่ชอบมนุษย์ค่ะ"
L1_1.m_Talk_THA = L2_1
L2_1 = "Tôi không cần cải thiện mối quan hệ với cộng đồng. Tôi không thích con người."
L1_1.m_Talk_VTN = L2_1
L2_1 = "没必要改善关系。因为我讨厌人类。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Ich habe es nicht nötig, meine Beziehungen zu verbessern. Ich mag Menschen nicht."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Faire dans le social, ça ne m'intéresse pas. Je n'aime pas les humains."
L1_1.m_Talk_FRA = L2_1
