L5_1 = "HORIZON_ACT2_INTERLUDE1@254#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 254
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 3500201
L4_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_Face = "UNIT_PRIDE"
L5_1 = "RACHEL_NPC_NULL_NULL"
L4_1.m_CharStrID = L5_1
L5_1 = "R_M_I"
L4_1.m_Pos = L5_1
L5_1 = "에이, 그럼 평소처럼 입 꾹 다물고 심부름만 해. 자꾸 그러면 언니 간다?"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "じゃあ、いつものように黙って頼まれた仕事だけすればいいんじゃない？　ここはお姉ちゃんの言うこと聞いて？"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Fine, then. You don't have to talk to anyone. Just run a few errands. If you keep acting stubborn, I'm outta here."
L4_1.m_Talk_ENG = L5_1
L5_1 = "真是的，那你就像平時一樣，閉上嘴乖乖做事吧。你再這樣頂嘴姊姊要走囉？"
L4_1.m_Talk_TWN = L5_1
L5_1 = "อะ งั้นเธอก็ไม่ต้องคุยกับใคร ก็แค่ทำธุระสองสามอย่าง ถ้าจะยังดื้อแบบนี้ฉันก็ลาละ"
L4_1.m_Talk_THA = L5_1
L5_1 = "Tốt thôi. Em không cần phải nói chuyện với bất cứ ai. Chỉ cần chạy một vài việc vặt. Nếu cứ bướng bỉnh không muốn, chị sẽ ra khỏi đây."
L4_1.m_Talk_VTN = L5_1
L5_1 = "唉，你只要像平时那样不说话帮忙跑腿就可以了。如果你总这样，姐姐要走了噢？"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Okay dann. Du musst mit niemandem reden. Nur ein paar Besorgungen machen. Wenn du dich weiterhin stur benimmst, gehe ich."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Bon, bon ! Dans ce cas, tu pourras toujours remplir ta mission en silence. Si tu continues à t'obstiner, je m'en vais !"
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
