L7_1 = "구체적으로 어떤 일을 도우면 됩니까?"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "具体的にどんな仕事を手伝えばいいですか？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Specifically, what will I be assisting them with?"
L6_1.m_Talk_ENG = L7_1
L7_1 = "所以是要幫忙什麼？"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ขอชัดๆ ซิคะ ฉันต้องช่วยอะไรพวกเขา?"
L6_1.m_Talk_THA = L7_1
L7_1 = "Cụ thể, tôi sẽ hỗ trợ họ những gì?"
L6_1.m_Talk_VTN = L7_1
L7_1 = "具体需要帮忙做什么工作？"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Wobei werde ich konkret helfen?"
L6_1.m_Talk_DEU = L7_1
L7_1 = "C'est quel genre de mission, exactement ?"
L6_1.m_Talk_FRA = L7_1
