L9_1 = "SEONGTAE_MILITIA_NULL_NULL"
L8_1.m_CharStrID = L9_1
L8_1.m_Pos = "C"
L9_1 = "침식지대에 있는 통신중계소가 먹통이 됐어. 30분 뒤에 수리하러 갈 예정이다."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "侵食地帯にある通信中継所が使えなくなってな。30分後に修理しに行く予定だ。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "The communication relay station in the Corrupted Area is out of order. We'll head there for repairs in about half an hour."
L8_1.m_Talk_ENG = L9_1
L9_1 = "侵蝕地區的通信基地台有點問題，預計半小時後要去修理。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "สถานีถ่ายทอดสัญญาณการสื่อสารในบริเวณที่ถูกคอร์รัปต์พังน่ะ เราต้องไปซ่อมในครึ่งชั่วโมง"
L8_1.m_Talk_THA = L9_1
L9_1 = "Trạm chuyển tiếp thông tin liên lạc trong Khu Vực Bị Ăn Mòn không hoạt động. Chúng tôi sẽ đến đó để sửa chữa trong khoảng nửa giờ nữa."
L8_1.m_Talk_VTN = L9_1
L9_1 = "侵蚀地区的通信中转站出现了故障。预计在30分钟后去修理。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Die Relaisstation im Verderbten Gebiet ist außer Betrieb. Wir fahren in etwa einer halben Stunde zur Reparatur dorthin."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Notre relais de communication situé dans la Zone Corrompue est hors service. Nous partons le réparer dans 30 minutes."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "HORIZON_ACT2_INTERLUDE1@259#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 259
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 3500201
L9_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L9_1.m_bWaitClick = true
