L10_1 = "SEONGTAE_MILITIA_NULL_NULL"
L9_1.m_CharStrID = L10_1
L9_1.m_Pos = "C"
L10_1 = "고치는 동안 너는 옆에서 공구들만 챙겨 주면 돼. 간단하지."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "それを直している間、隣で工具を用意してくれればいい。簡単だろ。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "All you need to do is hand us the tools while we fix it. It's simple as that."
L9_1.m_Talk_ENG = L10_1
L10_1 = "你只需要在修理的時候，在一旁看著工具就好，很簡單吧？"
L9_1.m_Talk_TWN = L10_1
L10_1 = "เธอก็แค่ต้องคอยส่งเครื่องมือให้ตอนเราซ่อม แค่นั้นแหละ"
L9_1.m_Talk_THA = L10_1
L10_1 = "Tất cả những gì cần làm là giao công cụ cho mọi người trong khi sửa chữa nó. Chỉ đơn giản như vậy thôi."
L9_1.m_Talk_VTN = L10_1
L10_1 = "在修理期间，你只要在旁边帮忙递工具就可以了。很简单吧。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Alles, was du tun musst, ist, uns die Werkzeuge zu reichen, während wir es reparieren. So einfach ist das."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Tout ce que je te demande, c'est de nous passer les outils dont on a besoin pendant l'opération."
L9_1.m_Talk_FRA = L10_1
