L16_1.m_CharStrID = L17_1
L16_1.m_Pos = "L"
L17_1 = "자경단에 바람 넣은 사람은 너 아니었나?"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "自警団に入れてやれと散々言ってたのはあんただろ？"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Wasn't it your idea to sweet talk the neighborhood watch into this?"
