L16_1.m_Talk_THA = L17_1
L17_1 = "Chẳng phải em đã nói ngon nói ngọt với cảnh vệ khu phố về chuyện này sao?"
L16_1.m_Talk_VTN = L17_1
L17_1 = "不是你拜托的自卫队的人吗？"
L16_1.m_Talk_SCN = L17_1
L17_1 = "War es nicht deine Idee, die Stadtwache zu überreden?"
