L18_1.m_CharStrID = L19_1
L18_1.m_Pos = "R"
L19_1 = "좋아. 호라이즌. 가서 사고치지 말고 네 실력을 보여 주는 거야."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "よし、ホライズン。トラブルは起こさないで、あんたの実力を見せてやりなよ。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "That's great, Horizon. Go show them what you got, and do try to stay out of trouble, will you?"
L18_1.m_Talk_ENG = L19_1
L19_1 = "好吧，地平線。你去上班後不要惹事，要展現你的實力。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "เยี่ยมเลยฮอไรซัน ไปโชว์ให้พวกนั้นดูเลยว่าเธอมีดีอะไร แต่อย่าหาเหาใส่หัวล่ะ ได้มั้ย?"
L18_1.m_Talk_THA = L19_1
L19_1 = "Thật tuyệt, Horizon. Hãy cho họ thấy những gì em có thể làm được, và cố gắng tránh xa rắc rối, được không?"
L18_1.m_Talk_VTN = L19_1
L19_1 = "那好吧。地平线。去了之后别惹麻烦，让大家见识下你的实力。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Okay, Horizon. Zeig ihnen, was du kannst, und versuche, Ärger zu vermeiden, ja?"
L18_1.m_Talk_DEU = L19_1
L19_1 = "C'est super, Horizon ! Montre leur un peu ce que tu sais faire et surtout ne cause pas d'ennuis, d'accord ?"
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "HORIZON_ACT2_INTERLUDE1@269#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 269
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 3500201
L19_1.m_CutScenStrID = "HORIZON_ACT2_INTERLUDE1"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L20_1 = "RACHEL_NPC_NULL_NULL"
L19_1.m_CharStrID = L20_1
L19_1.m_Pos = "R"
L20_1 = "잘하고 오면 언니가 침대에서 찐~한 상을 줄게?"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "頑張ってきたらお姉ちゃんがベッドの上でご褒美をあげるから。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "I'll give you a juicy reward in bed if you do a good job, okay?"
L19_1.m_Talk_ENG = L20_1
L20_1 = "做得好的話，姊姊會在床上給你獎勵喔？"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ถ้างานออกมาดีฉันจะหารางวัลงามๆ ไปให้ถึงเตียงเลยนะ โอเค้?"
L19_1.m_Talk_THA = L20_1
L20_1 = "Chị sẽ thưởng cho nhóc một phần thưởng hấp dẫn trên giường nếu em làm tốt công việc của mình, được không?"
L19_1.m_Talk_VTN = L20_1
L20_1 = "如果做得好，姐姐可以在床上给你奖励哦？"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Ich gebe dir eine besondere Belohnung im Bett, wenn du gut bist, okay?"
L19_1.m_Talk_DEU = L20_1
L20_1 = "Si tu fais du bon travail, je te récompenserai comme il faut au lit !"
L19_1.m_Talk_FRA = L20_1
