L21_1.m_Pos = "C"
L22_1 = "침대에서 저를 상대하면 몸이 남아나지 않을 겁니다. 휴먼."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "ベッドで私の相手をしたら身がもたないと思いますよ、ヒューマン。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "You can't handle me in bed, human."
L21_1.m_Talk_ENG = L22_1
L22_1 = "在床上交手的話，你可能會小命不保，人類。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "คุณรับมือฉันบนเตียงไม่ไหวหรอกค่ะมนุษย์"
L21_1.m_Talk_THA = L22_1
L22_1 = "Cô không thể xử lý tôi trên giường đâu, con người."
L21_1.m_Talk_VTN = L22_1
L22_1 = "如果在床上交手的话，你可能连渣都不会剩下，人类。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Im Bett wirst du schwach gegen mich sein, Mensch."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Au lit ? Si j'étais vous, j'y réfléchirais à deux fois. Votre corps n'y survivrait pas."
L21_1.m_Talk_FRA = L22_1
