L25_1 = "UNIT_SERIOUS"
L24_1.m_Face = L25_1
L25_1 = "RACHEL_NPC_NULL_NULL"
L24_1.m_CharStrID = L25_1
L24_1.m_Pos = "C"
L24_1.m_Crash = 20
L25_1 = "너, 너너너어어! 언니 모르게 어디서 그런 발랑 까진 말을 배웠어?!"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "あ、あ、あ、あんた！　どこでそんな不純な表現を身につけたの！？"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Why, you little! Where did you learn to say something so naughty?!"
L24_1.m_Talk_ENG = L25_1
L25_1 = "你你你！你趁我不注意，去哪學這些五四三的話？！"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ตายแล้วยัยเปี๊ยก! ไปเรียนคำพูดคำจาสัปดี้สัปดนแบบนั้นมาจากไหนเนี่ย?!"
L24_1.m_Talk_THA = L25_1
L25_1 = "Cái cô nhóc này! Nhóc đã học ở đâu để nói xằng xiên như thế hả?!"
L24_1.m_Talk_VTN = L25_1
L25_1 = "你、你你你什么时候学会说这种话的？！"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Hey, h-h-h-h-h-hey! Wo hast du gelernt, so etwas Unartiges zu sagen?!"
L24_1.m_Talk_DEU = L25_1
L25_1 = "Ça va pas la tête ? Où as-tu appris à parler comme ça ?"
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "HORIZON_ACT2_INTERLUDE1@275#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 275
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 3500201
