L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L25_1.m_Pos = "C"
L26_1 = "당신들이 만든 정보의 폐수처리장에서 배웠죠."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "あなたたち、ヒューマンが作った情報の汚水処理場で学習しました。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "I learned it from the cesspool of information you humans created."
L25_1.m_Talk_ENG = L26_1
L26_1 = "我是在你們創造的資訊汙水處理廠學的。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ก็รู้มาจากข้อมูลในแหล่งเสื่อมโทรมที่พวกมนุษย์อย่างคุณสร้างขึ้นนั่นแหละค่ะ"
L25_1.m_Talk_THA = L26_1
L26_1 = "Tôi đã học được điều đó từ kho thông tin mà con người tạo ra."
L25_1.m_Talk_VTN = L26_1
L26_1 = "我是从你们人类自己创造的信息垃圾中学来的。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Ich habe es aus der Kloake an Informationen gelernt, die ihr Menschen geschaffen habt."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Directement dans la fosse d'informations que vous avez créée."
L25_1.m_Talk_FRA = L26_1
