L30_1 = "……你和瑞秋老是這樣吵吵鬧鬧嗎？"
L29_1.m_Talk_TWN = L30_1
L30_1 = "นี่เธอกับเรเชลคุยกันเจี๊ยวจ๊าวแบบนี้ตลอดเลยเหรอ?"
